__CR('t:ml',[{"t":"머신러닝이란","l":[{"t":"학습의 세 가지 유형","q":[{"t":"choice","k":"지도학습","q":"지도학습(supervised learning)을 가장 잘 설명한 것은?","o":["정답 레이블이 있는 데이터로 입력과 출력의 관계를 학습한다","레이블 없이 데이터의 숨은 구조를 찾는다","보상 신호를 통해 시행착오로 행동을 학습한다","사람이 모든 규칙을 직접 코드로 작성한다"],"a":0,"ex":"지도학습은 입력(특성)과 정답(레이블)이 쌍으로 주어진 데이터로 둘 사이의 대응 관계를 학습합니다."},{"t":"choice","k":"비지도학습","q":"레이블이 전혀 없는 고객 데이터를 비슷한 집단으로 묶는 작업은 어떤 유형인가?","o":["지도학습","비지도학습","강화학습","규칙기반 프로그래밍"],"a":1,"ex":"정답 레이블 없이 데이터 자체의 구조(유사성)를 찾아 군집화(clustering)하는 것은 비지도학습입니다."},{"t":"input","k":"레이블 없음","q":"정답 레이블 없이 데이터의 패턴이나 구조를 스스로 찾는 학습 유형의 이름은? (한국어)","a":["비지도학습","비지도 학습","unsupervised learning"],"ex":"비지도학습(unsupervised learning)은 레이블 없이 군집화, 차원 축소 등으로 데이터의 내재된 구조를 발견합니다."},{"t":"choice","k":"스팸분류","q":"'스팸/정상'이 표시된 이메일 데이터로 필터를 학습시키는 것은 어떤 유형인가?","o":["비지도학습","강화학습","지도학습","특성 선택"],"a":2,"ex":"스팸/정상이라는 정답 레이블이 있으므로 지도학습이며, 그중에서도 두 범주로 나누는 분류(classification) 문제입니다."}],"th":{"sum":"머신러닝은 **지도학습**(정답 있음), **비지도학습**(정답 없음, 패턴 발견), **강화학습**(보상으로 학습)으로 나뉜다. 지도학습은 다시 분류와 회귀로 구분된다.","body":[{"h":"학습의 세 유형","t":"**지도학습**은 입력과 정답 레이블 쌍으로 배운다(스팸/정상 이메일 필터). **비지도학습**은 레이블 없이 데이터의 구조·군집을 스스로 찾는다(고객 세분화 클러스터링). **강화학습**은 환경과 상호작용하며 보상을 최대화하도록 학습한다(게임 AI, 로봇 제어)."},{"h":"분류와 회귀","t":"지도학습은 출력 형태로 나뉜다. **분류(classification)**는 이산적 범주(스팸/정상, 개/고양이)를 예측하고, **회귀(regression)**는 연속적 수치(집값, 기온)를 예측한다. 데이터는 보통 **특성(feature)**과 **레이블(label/target)**로 구성된다."}],"code":{"c":"# 지도학습:   (X, y) → 정답 y 존재\n#   분류: y가 범주 (스팸/정상)\n#   회귀: y가 연속값 (집값)\n# 비지도학습: (X)   → 레이블 없이 군집/패턴\n# 강화학습:   보상(reward)으로 정책 학습","cap":"정답 유무와 출력 형태로 학습 유형 구분"},"key":["지도=정답 있음, 비지도=정답 없이 패턴, 강화=보상으로 학습","클러스터링(군집화)은 비지도학습","분류=이산 범주 예측, 회귀=연속 수치 예측","데이터=특성(feature)+레이블(label)"]}},{"t":"분류와 회귀","q":[{"t":"choice","k":"회귀정의","q":"회귀(regression) 문제의 특징으로 옳은 것은?","o":["출력이 정해진 몇 개의 범주 중 하나이다","출력이 연속적인 수치 값이다","레이블이 존재하지 않는다","보상을 통해 학습한다"],"a":1,"ex":"회귀는 집값, 온도처럼 연속적인 수치를 예측합니다. 반면 분류는 이산적인 범주(class)를 예측합니다."},{"t":"input","k":"스팸/정상","q":"이메일을 '스팸' 또는 '정상' 두 범주 중 하나로 예측하는 지도학습 문제 유형은? (한국어)","a":["분류","classification"],"ex":"정해진 범주 중 하나를 고르므로 분류(classification)이며, 범주가 둘이므로 이진 분류입니다."}],"th":{"sum":"머신러닝은 **지도학습**(정답 있음), **비지도학습**(정답 없음, 패턴 발견), **강화학습**(보상으로 학습)으로 나뉜다. 지도학습은 다시 분류와 회귀로 구분된다.","body":[{"h":"학습의 세 유형","t":"**지도학습**은 입력과 정답 레이블 쌍으로 배운다(스팸/정상 이메일 필터). **비지도학습**은 레이블 없이 데이터의 구조·군집을 스스로 찾는다(고객 세분화 클러스터링). **강화학습**은 환경과 상호작용하며 보상을 최대화하도록 학습한다(게임 AI, 로봇 제어)."},{"h":"분류와 회귀","t":"지도학습은 출력 형태로 나뉜다. **분류(classification)**는 이산적 범주(스팸/정상, 개/고양이)를 예측하고, **회귀(regression)**는 연속적 수치(집값, 기온)를 예측한다. 데이터는 보통 **특성(feature)**과 **레이블(label/target)**로 구성된다."}],"code":{"c":"# 지도학습:   (X, y) → 정답 y 존재\n#   분류: y가 범주 (스팸/정상)\n#   회귀: y가 연속값 (집값)\n# 비지도학습: (X)   → 레이블 없이 군집/패턴\n# 강화학습:   보상(reward)으로 정책 학습","cap":"정답 유무와 출력 형태로 학습 유형 구분"},"key":["지도=정답 있음, 비지도=정답 없이 패턴, 강화=보상으로 학습","클러스터링(군집화)은 비지도학습","분류=이산 범주 예측, 회귀=연속 수치 예측","데이터=특성(feature)+레이블(label)"]}},{"t":"데이터의 구성 요소","q":[{"t":"choice","k":"특성","q":"머신러닝에서 특성(feature)이란?","o":["예측하려는 정답 값","모델의 성능 지표","입력을 설명하는 개별 속성(변수)","전체 데이터셋의 크기"],"a":2,"ex":"특성(feature)은 예측에 사용하는 입력 변수입니다. 예: 집의 면적, 방 개수. 특성들의 조합으로 하나의 샘플이 표현됩니다."},{"t":"input","k":"정답값","q":"지도학습에서 각 샘플에 대해 모델이 맞혀야 하는 정답 값을 부르는 용어는? (한국어)","a":["레이블","라벨","label","타깃","target"],"ex":"정답 값은 레이블(label) 또는 타깃(target)이라고 합니다."}],"th":{"sum":"머신러닝은 **지도학습**(정답 있음), **비지도학습**(정답 없음, 패턴 발견), **강화학습**(보상으로 학습)으로 나뉜다. 지도학습은 다시 분류와 회귀로 구분된다.","body":[{"h":"학습의 세 유형","t":"**지도학습**은 입력과 정답 레이블 쌍으로 배운다(스팸/정상 이메일 필터). **비지도학습**은 레이블 없이 데이터의 구조·군집을 스스로 찾는다(고객 세분화 클러스터링). **강화학습**은 환경과 상호작용하며 보상을 최대화하도록 학습한다(게임 AI, 로봇 제어)."},{"h":"분류와 회귀","t":"지도학습은 출력 형태로 나뉜다. **분류(classification)**는 이산적 범주(스팸/정상, 개/고양이)를 예측하고, **회귀(regression)**는 연속적 수치(집값, 기온)를 예측한다. 데이터는 보통 **특성(feature)**과 **레이블(label/target)**로 구성된다."}],"code":{"c":"# 지도학습:   (X, y) → 정답 y 존재\n#   분류: y가 범주 (스팸/정상)\n#   회귀: y가 연속값 (집값)\n# 비지도학습: (X)   → 레이블 없이 군집/패턴\n# 강화학습:   보상(reward)으로 정책 학습","cap":"정답 유무와 출력 형태로 학습 유형 구분"},"key":["지도=정답 있음, 비지도=정답 없이 패턴, 강화=보상으로 학습","클러스터링(군집화)은 비지도학습","분류=이산 범주 예측, 회귀=연속 수치 예측","데이터=특성(feature)+레이블(label)"]}}]},{"t":"학습과 일반화","l":[{"t":"데이터 분할","q":[{"t":"input","k":"파라미터학습","q":"모델의 파라미터를 실제로 학습(fit)시키는 데 사용하는 데이터 세트의 이름은? (한국어)","a":["훈련 세트","훈련셋","트레이닝 세트","학습 세트","train"],"ex":"모델 파라미터는 훈련 세트(training set)로 학습합니다."},{"t":"choice","k":"테스트오용","q":"테스트 세트를 반복적으로 보며 하이퍼파라미터를 고르면 생기는 문제는?","o":["훈련 속도가 느려진다","테스트 세트에 간접적으로 과적합되어 일반화 성능을 과대평가한다","레이블이 사라진다","특성 수가 늘어난다"],"a":1,"ex":"테스트 세트로 튜닝하면 그 세트에 맞춰지게 되어, 더 이상 편향 없는 일반화 성능 추정이 불가능해집니다."}],"th":{"sum":"데이터를 **훈련/검증/테스트**로 나눠 학습·튜닝·최종평가를 분리한다. **과적합**은 훈련만 잘하고 새 데이터에 약한 상태, **과소적합**은 훈련조차 못하는 상태다.","body":[{"h":"데이터 분할","t":"**훈련 세트**로 모델 파라미터를 실제로 학습(fit)하고, **검증 세트**로 하이퍼파라미터를 고르며, **테스트 세트**는 마지막에 딱 한 번 일반화 성능을 평가할 때만 쓴다. 테스트 세트를 반복해서 보며 튜닝하면 그 세트에 정보가 새어(데이터 누수) 성능이 부풀려진다."},{"h":"과적합·과소적합·교차검증","t":"**과적합(overfitting)**은 훈련 정확도는 높은데 검증/테스트 정확도가 낮은 상태(모델이 노이즈까지 암기). **과소적합(underfitting)**은 모델이 너무 단순해 훈련 성능조차 낮은 상태다. **교차검증(k-fold)**은 데이터를 여러 겹으로 나눠 번갈아 검증해 평가를 안정화한다. 전처리 통계는 훈련 데이터로만 학습해 누수를 막는다."}],"code":{"c":"# 훈련 세트  → 파라미터 fit\n# 검증 세트  → 하이퍼파라미터 선택\n# 테스트 세트 → 최종 1회 평가만\n# 과적합: train↑ / val↓\n# 과소적합: train↓ / val↓","cap":"세 세트를 분리해야 일반화 성능을 정직하게 측정"},"key":["훈련=fit, 검증=하이퍼파라미터 선택, 테스트=최종 1회 평가","테스트 세트 반복 사용은 데이터 누수 → 성능 과대평가","과적합=train↑ val↓, 과소적합=둘 다↓","교차검증(k-fold)으로 평가 안정화"]}},{"t":"과적합과 과소적합","q":[{"t":"choice","k":"편향분산","q":"편향-분산 트레이드오프(bias-variance trade-off)를 옳게 설명한 것은?","o":["편향과 분산은 항상 함께 커진다","모델을 복잡하게 하면 편향은 줄지만 분산은 커지는 경향이 있다","분산은 데이터 개수와 무관하다","편향을 없애면 분산도 항상 0이 된다"],"a":1,"ex":"복잡한 모델일수록 편향(과소적합 경향)은 줄지만 분산(과적합 경향)은 커집니다. 둘의 균형점을 찾는 것이 목표입니다."},{"t":"input","k":"외움현상","q":"훈련 데이터에는 매우 잘 맞지만 새로운 데이터에서는 성능이 크게 떨어지는 현상의 이름은? (한국어)","a":["과적합","오버피팅","overfitting"],"ex":"이 현상은 과적합(overfitting)이며, 모델이 훈련 데이터의 잡음까지 외운 결과입니다."}],"th":{"sum":"데이터를 **훈련/검증/테스트**로 나눠 학습·튜닝·최종평가를 분리한다. **과적합**은 훈련만 잘하고 새 데이터에 약한 상태, **과소적합**은 훈련조차 못하는 상태다.","body":[{"h":"데이터 분할","t":"**훈련 세트**로 모델 파라미터를 실제로 학습(fit)하고, **검증 세트**로 하이퍼파라미터를 고르며, **테스트 세트**는 마지막에 딱 한 번 일반화 성능을 평가할 때만 쓴다. 테스트 세트를 반복해서 보며 튜닝하면 그 세트에 정보가 새어(데이터 누수) 성능이 부풀려진다."},{"h":"과적합·과소적합·교차검증","t":"**과적합(overfitting)**은 훈련 정확도는 높은데 검증/테스트 정확도가 낮은 상태(모델이 노이즈까지 암기). **과소적합(underfitting)**은 모델이 너무 단순해 훈련 성능조차 낮은 상태다. **교차검증(k-fold)**은 데이터를 여러 겹으로 나눠 번갈아 검증해 평가를 안정화한다. 전처리 통계는 훈련 데이터로만 학습해 누수를 막는다."}],"code":{"c":"# 훈련 세트  → 파라미터 fit\n# 검증 세트  → 하이퍼파라미터 선택\n# 테스트 세트 → 최종 1회 평가만\n# 과적합: train↑ / val↓\n# 과소적합: train↓ / val↓","cap":"세 세트를 분리해야 일반화 성능을 정직하게 측정"},"key":["훈련=fit, 검증=하이퍼파라미터 선택, 테스트=최종 1회 평가","테스트 세트 반복 사용은 데이터 누수 → 성능 과대평가","과적합=train↑ val↓, 과소적합=둘 다↓","교차검증(k-fold)으로 평가 안정화"]}},{"t":"교차검증과 데이터 누수","q":[{"t":"choice","k":"데이터누수","q":"데이터 누수(data leakage)란?","o":["훈련 데이터가 손상되어 사라지는 것","테스트/미래 시점의 정보가 학습 과정에 새어 들어가 성능이 부풀려지는 것","데이터 파일 용량이 커지는 것","레이블이 부족한 것"],"a":1,"ex":"데이터 누수는 실제 예측 시점에 알 수 없는 정보(예: 테스트 세트 통계)가 학습에 포함되어, 성능이 비현실적으로 좋게 나오는 문제입니다."},{"t":"input","k":"폴드수","q":"5-겹 교차검증(k=5)에서는 모델을 총 몇 번 학습·평가하는가? (숫자)","a":["5","다섯","5번"],"ex":"k=5이면 각 폴드를 한 번씩 검증에 사용하므로 총 5회 학습·평가하고 그 결과를 평균냅니다."}],"th":{"sum":"데이터를 **훈련/검증/테스트**로 나눠 학습·튜닝·최종평가를 분리한다. **과적합**은 훈련만 잘하고 새 데이터에 약한 상태, **과소적합**은 훈련조차 못하는 상태다.","body":[{"h":"데이터 분할","t":"**훈련 세트**로 모델 파라미터를 실제로 학습(fit)하고, **검증 세트**로 하이퍼파라미터를 고르며, **테스트 세트**는 마지막에 딱 한 번 일반화 성능을 평가할 때만 쓴다. 테스트 세트를 반복해서 보며 튜닝하면 그 세트에 정보가 새어(데이터 누수) 성능이 부풀려진다."},{"h":"과적합·과소적합·교차검증","t":"**과적합(overfitting)**은 훈련 정확도는 높은데 검증/테스트 정확도가 낮은 상태(모델이 노이즈까지 암기). **과소적합(underfitting)**은 모델이 너무 단순해 훈련 성능조차 낮은 상태다. **교차검증(k-fold)**은 데이터를 여러 겹으로 나눠 번갈아 검증해 평가를 안정화한다. 전처리 통계는 훈련 데이터로만 학습해 누수를 막는다."}],"code":{"c":"# 훈련 세트  → 파라미터 fit\n# 검증 세트  → 하이퍼파라미터 선택\n# 테스트 세트 → 최종 1회 평가만\n# 과적합: train↑ / val↓\n# 과소적합: train↓ / val↓","cap":"세 세트를 분리해야 일반화 성능을 정직하게 측정"},"key":["훈련=fit, 검증=하이퍼파라미터 선택, 테스트=최종 1회 평가","테스트 세트 반복 사용은 데이터 누수 → 성능 과대평가","과적합=train↑ val↓, 과소적합=둘 다↓","교차검증(k-fold)으로 평가 안정화"]}}]},{"t":"데이터 준비","l":[{"t":"특성 스케일링","q":[{"t":"choice","k":"정규화","q":"최소-최대 정규화(min-max normalization)는 값을 어떤 범위로 변환하는가?","o":["-1에서 1","보통 0에서 1","0에서 100 정수","평균 0, 분산 무관"],"a":1,"ex":"최소-최대 정규화는 (x-min)/(max-min)으로 계산하여 값을 일반적으로 0~1 범위로 변환합니다."},{"t":"input","k":"평균0분산1","q":"각 특성을 평균 0, 표준편차 1로 변환하는 스케일링 방법의 이름은? (한국어)","a":["표준화","standardization","z-점수 정규화"],"ex":"평균 0·표준편차 1로 만드는 것은 표준화(standardization)이며 z-점수 변환이라고도 합니다."}],"th":{"sum":"**특성 스케일링**으로 특성 범위를 맞추고, **인코딩**으로 범주형을 수치화하며, 결측치·불균형을 처리한다. 스케일러는 훈련 데이터로만 fit해야 한다.","body":[{"h":"스케일링","t":"거리·경사 기반 알고리즘(KNN, SVM, 경사하강법)은 특성 크기 차이에 민감해 **스케일링**이 필요하다. **표준화(standardization)**는 평균 0, 표준편차 1로 바꾸고, **최소-최대 정규화(min-max)**는 값을 0~1 범위로 변환한다. 스케일러는 **훈련 데이터로 fit**한 뒤 같은 기준으로 검증/테스트를 transform해야 누수를 막는다."},{"h":"인코딩과 불균형","t":"모델은 숫자만 다루므로 범주형 특성을 수치로 **인코딩**한다. **원-핫 인코딩**은 각 범주를 0/1 열로 펼쳐, 크기에 순서 의미가 없는 명목형에 적합하다. 결측치는 삭제·대치(imputation)로, 클래스 **불균형**은 리샘플링·가중치로 다룬다. 불필요한 특성은 특성 선택으로 줄인다."}],"code":{"c":"from sklearn.preprocessing import StandardScaler\nscaler = StandardScaler()\nscaler.fit(X_train)             # 훈련으로만 fit\nX_train = scaler.transform(X_train)\nX_test  = scaler.transform(X_test)  # 같은 기준 적용","cap":"fit은 훈련 데이터로만, transform은 동일 기준 적용"},"key":["거리·경사 기반 모델은 스케일링 필요","표준화=평균0·표준편차1, min-max=0~1 범위","스케일러는 훈련으로만 fit → 데이터 누수 방지","원-핫 인코딩=범주를 0/1 열로, 순서 없는 명목형에 적합"]}},{"t":"인코딩과 결측치","q":[{"t":"choice","k":"결측치","q":"결측치(missing value)를 처리하는 방법으로 적절하지 않은 것은?","o":["평균·중앙값·최빈값으로 대치(imputation)","해당 행 또는 열 삭제","모델 기반 예측으로 채우기","결측치를 무시하고 문자열 그대로 학습에 투입"],"a":3,"ex":"대부분의 수치 모델은 결측치를 직접 다루지 못하므로, 대치나 삭제 등으로 처리해야 합니다. 그대로 투입하는 것은 부적절합니다."},{"t":"choice","k":"원핫차원","q":"순서가 없는 범주형 특성이 5개의 서로 다른 값을 가질 때, 원-핫 인코딩하면 보통 몇 개의 열이 생기는가?","o":["1개","5개","25개","0개"],"a":1,"ex":"원-핫 인코딩은 범주 수만큼 열을 만들므로 5개 범주는 5개 열이 됩니다(다중공선성 방지를 위해 하나를 빼기도 함)."},{"t":"input","k":"0/1벡터","q":"'빨강, 파랑, 초록' 같은 순서 없는 범주를 각각 0과 1로 이루어진 벡터로 바꾸는 인코딩 방법의 이름은? (한국어)","a":["원-핫 인코딩","원핫 인코딩","원핫","one-hot encoding","원핫인코딩"],"ex":"순서 없는 범주는 크기 관계를 부여하지 않도록 원-핫 인코딩으로 표현합니다."}],"th":{"sum":"**특성 스케일링**으로 특성 범위를 맞추고, **인코딩**으로 범주형을 수치화하며, 결측치·불균형을 처리한다. 스케일러는 훈련 데이터로만 fit해야 한다.","body":[{"h":"스케일링","t":"거리·경사 기반 알고리즘(KNN, SVM, 경사하강법)은 특성 크기 차이에 민감해 **스케일링**이 필요하다. **표준화(standardization)**는 평균 0, 표준편차 1로 바꾸고, **최소-최대 정규화(min-max)**는 값을 0~1 범위로 변환한다. 스케일러는 **훈련 데이터로 fit**한 뒤 같은 기준으로 검증/테스트를 transform해야 누수를 막는다."},{"h":"인코딩과 불균형","t":"모델은 숫자만 다루므로 범주형 특성을 수치로 **인코딩**한다. **원-핫 인코딩**은 각 범주를 0/1 열로 펼쳐, 크기에 순서 의미가 없는 명목형에 적합하다. 결측치는 삭제·대치(imputation)로, 클래스 **불균형**은 리샘플링·가중치로 다룬다. 불필요한 특성은 특성 선택으로 줄인다."}],"code":{"c":"from sklearn.preprocessing import StandardScaler\nscaler = StandardScaler()\nscaler.fit(X_train)             # 훈련으로만 fit\nX_train = scaler.transform(X_train)\nX_test  = scaler.transform(X_test)  # 같은 기준 적용","cap":"fit은 훈련 데이터로만, transform은 동일 기준 적용"},"key":["거리·경사 기반 모델은 스케일링 필요","표준화=평균0·표준편차1, min-max=0~1 범위","스케일러는 훈련으로만 fit → 데이터 누수 방지","원-핫 인코딩=범주를 0/1 열로, 순서 없는 명목형에 적합"]}},{"t":"불균형과 특성 선택","q":[{"t":"choice","k":"불균형대응","q":"클래스 불균형에 대응하는 방법이 아닌 것은?","o":["소수 클래스 오버샘플링","다수 클래스 언더샘플링","클래스 가중치 조정","모든 데이터를 무작위로 삭제"],"a":3,"ex":"오버샘플링, 언더샘플링, 클래스 가중치, 적절한 평가지표(F1 등)가 대응책입니다. 데이터를 무작위로 통째 삭제하는 것은 해법이 아닙니다."},{"t":"input","k":"소수복제","q":"소수 클래스의 샘플을 늘려 클래스 균형을 맞추는 기법을 무엇이라 하는가? (한국어)","a":["오버샘플링","오버 샘플링","oversampling","과대표집"],"ex":"소수 클래스를 복제하거나 합성(예: SMOTE)해 늘리는 것을 오버샘플링(oversampling)이라 합니다."}],"th":{"sum":"**특성 스케일링**으로 특성 범위를 맞추고, **인코딩**으로 범주형을 수치화하며, 결측치·불균형을 처리한다. 스케일러는 훈련 데이터로만 fit해야 한다.","body":[{"h":"스케일링","t":"거리·경사 기반 알고리즘(KNN, SVM, 경사하강법)은 특성 크기 차이에 민감해 **스케일링**이 필요하다. **표준화(standardization)**는 평균 0, 표준편차 1로 바꾸고, **최소-최대 정규화(min-max)**는 값을 0~1 범위로 변환한다. 스케일러는 **훈련 데이터로 fit**한 뒤 같은 기준으로 검증/테스트를 transform해야 누수를 막는다."},{"h":"인코딩과 불균형","t":"모델은 숫자만 다루므로 범주형 특성을 수치로 **인코딩**한다. **원-핫 인코딩**은 각 범주를 0/1 열로 펼쳐, 크기에 순서 의미가 없는 명목형에 적합하다. 결측치는 삭제·대치(imputation)로, 클래스 **불균형**은 리샘플링·가중치로 다룬다. 불필요한 특성은 특성 선택으로 줄인다."}],"code":{"c":"from sklearn.preprocessing import StandardScaler\nscaler = StandardScaler()\nscaler.fit(X_train)             # 훈련으로만 fit\nX_train = scaler.transform(X_train)\nX_test  = scaler.transform(X_test)  # 같은 기준 적용","cap":"fit은 훈련 데이터로만, transform은 동일 기준 적용"},"key":["거리·경사 기반 모델은 스케일링 필요","표준화=평균0·표준편차1, min-max=0~1 범위","스케일러는 훈련으로만 fit → 데이터 누수 방지","원-핫 인코딩=범주를 0/1 열로, 순서 없는 명목형에 적합"]}}]},{"t":"편향-분산 트레이드오프 (중급)","l":[{"t":"편향과 분산 이해하기","q":[{"t":"choice","k":"복잡도와 관계","q":"모델 복잡도를 계속 높일 때 일반적으로 나타나는 변화는?","ex":"복잡한 모델일수록 데이터를 잘 맞추지만(편향↓) 표본 변화에 민감해진다(분산↑). 이것이 트레이드오프다.","o":["편향은 감소하고 분산은 증가한다","편향과 분산이 함께 감소한다","편향은 증가하고 분산은 감소한다","편향과 분산이 모두 변하지 않는다"],"a":0},{"t":"choice","k":"고분산 처방","q":"고분산(과적합)이 확인되었을 때 대응으로 적절하지 않은 것은?","ex":"용량을 더 키우면 분산이 더 커져 과적합이 심해진다. 나머지 셋은 모두 분산을 줄이는 표준적인 처방이다.","o":["모델을 더 복잡하게 만들어 용량을 키운다","훈련 데이터를 더 수집한다","L2 규제 강도를 높인다","기여도가 낮은 특성을 제거한다"],"a":0}],"th":{"sum":"예측 오차는 **편향**, **분산**, **줄일 수 없는 노이즈**로 나뉜다. 모델 복잡도를 올리면 편향은 줄고 분산은 커지는 **트레이드오프**가 생긴다.","body":[{"h":"편향과 분산의 정체","t":"**편향(bias)**은 모델이 너무 단순해 데이터의 참 관계를 담지 못해 생기는 체계적 오차다. **분산(variance)**은 훈련 데이터가 조금만 달라져도 학습 결과와 예측이 크게 흔들리는 정도다. 편향이 크면 과소적합으로, 분산이 크면 과적합으로 드러난다. 여기에 데이터 자체의 잡음에서 오는 **줄일 수 없는 오차**가 항상 더해지며, 이 값은 어떤 모델로도 제거할 수 없다."},{"h":"훈련·검증 오차로 진단하기","t":"훈련 오차와 검증 오차를 반드시 함께 본다. 둘 다 높으면 고편향(과소적합)이고, 훈련 오차만 낮은데 검증 오차와의 간격이 크게 벌어지면 고분산(과적합)이다. 고편향은 모델 용량을 키우거나 의미 있는 특성을 추가해 푼다. 고분산은 데이터를 더 모으거나 규제를 강화하고 불필요한 특성을 줄여서 푼다."},{"h":"학습곡선과 검증곡선","t":"**학습곡선**은 훈련 데이터 양에 따른 오차 변화를, **검증곡선**은 하이퍼파라미터 값에 따른 오차 변화를 그린다. 데이터를 늘려도 두 곡선이 높은 값에서 나란히 붙어 수렴하면 데이터가 아니라 모델이 문제인 고편향 상태다. 반대로 간격이 넓고 검증 곡선이 계속 내려가는 중이라면 데이터를 더 모으는 것이 유효하다."}],"code":{"c":"train 오차   val 오차   진단        처방\n  높음        높음     고편향     모델 용량↑, 특성 추가, 규제↓\n  낮음        높음     고분산     데이터↑, 규제↑, 특성 축소\n  낮음        낮음     양호       테스트 1회 평가 후 배포 검토\n\n총오차 = 편향² + 분산 + 노이즈(제거 불가)","cap":"훈련·검증 오차의 조합만으로 다음에 할 일이 정해진다"},"key":["편향↑ = 과소적합, 분산↑ = 과적합","복잡도를 올리면 편향은 줄고 분산은 커진다","노이즈(줄일 수 없는 오차)는 어떤 모델로도 0이 되지 않는다","훈련 오차 하나만 보고 판단하면 과적합을 놓친다"]}},{"t":"과적합·과소적합 진단","q":[{"t":"choice","k":"과적합 신호","q":"훈련 정확도 0.99, 검증 정확도 0.72인 모델에서 가장 먼저 의심할 상태는?","ex":"훈련 성능만 뛰어나고 검증에서 크게 무너지는 것이 과적합의 전형적인 신호다.","o":["과적합(고분산)","과소적합(고편향)","학습이 전혀 진행되지 않은 상태","모든 레이블이 동일한 상태"],"a":0},{"t":"choice","k":"간격이 넓을 때","q":"훈련 곡선과 검증 곡선의 간격이 매우 넓고 검증 곡선이 아직도 내려가는 중이라면?","ex":"간격이 넓으면 고분산이고, 검증 곡선이 개선 중이라면 데이터 추가로 격차를 더 좁힐 여지가 있다.","o":["데이터를 더 모으면 성능이 더 오를 가능성이 크다","이미 최적이므로 즉시 학습을 멈춰야 한다","반드시 모델을 더 복잡하게 만들어야 한다","테스트 세트를 훈련에 합쳐야 한다"],"a":0},{"t":"input","k":"격차 용어","q":"훈련 성능과 검증 성능의 차이를 가리키며, 이 값이 크면 과적합을 의심하게 되는 지표를 무엇이라 부르는가? (한글 용어)","ex":"일반화 격차(generalization gap)가 크다는 것은 모델이 훈련 데이터에만 잘 맞춰졌다는 뜻이다.","a":["일반화 격차","일반화격차","일반화 갭","generalization gap"]}],"th":{"sum":"예측 오차는 **편향**, **분산**, **줄일 수 없는 노이즈**로 나뉜다. 모델 복잡도를 올리면 편향은 줄고 분산은 커지는 **트레이드오프**가 생긴다.","body":[{"h":"편향과 분산의 정체","t":"**편향(bias)**은 모델이 너무 단순해 데이터의 참 관계를 담지 못해 생기는 체계적 오차다. **분산(variance)**은 훈련 데이터가 조금만 달라져도 학습 결과와 예측이 크게 흔들리는 정도다. 편향이 크면 과소적합으로, 분산이 크면 과적합으로 드러난다. 여기에 데이터 자체의 잡음에서 오는 **줄일 수 없는 오차**가 항상 더해지며, 이 값은 어떤 모델로도 제거할 수 없다."},{"h":"훈련·검증 오차로 진단하기","t":"훈련 오차와 검증 오차를 반드시 함께 본다. 둘 다 높으면 고편향(과소적합)이고, 훈련 오차만 낮은데 검증 오차와의 간격이 크게 벌어지면 고분산(과적합)이다. 고편향은 모델 용량을 키우거나 의미 있는 특성을 추가해 푼다. 고분산은 데이터를 더 모으거나 규제를 강화하고 불필요한 특성을 줄여서 푼다."},{"h":"학습곡선과 검증곡선","t":"**학습곡선**은 훈련 데이터 양에 따른 오차 변화를, **검증곡선**은 하이퍼파라미터 값에 따른 오차 변화를 그린다. 데이터를 늘려도 두 곡선이 높은 값에서 나란히 붙어 수렴하면 데이터가 아니라 모델이 문제인 고편향 상태다. 반대로 간격이 넓고 검증 곡선이 계속 내려가는 중이라면 데이터를 더 모으는 것이 유효하다."}],"code":{"c":"train 오차   val 오차   진단        처방\n  높음        높음     고편향     모델 용량↑, 특성 추가, 규제↓\n  낮음        높음     고분산     데이터↑, 규제↑, 특성 축소\n  낮음        낮음     양호       테스트 1회 평가 후 배포 검토\n\n총오차 = 편향² + 분산 + 노이즈(제거 불가)","cap":"훈련·검증 오차의 조합만으로 다음에 할 일이 정해진다"},"key":["편향↑ = 과소적합, 분산↑ = 과적합","복잡도를 올리면 편향은 줄고 분산은 커진다","노이즈(줄일 수 없는 오차)는 어떤 모델로도 0이 되지 않는다","훈련 오차 하나만 보고 판단하면 과적합을 놓친다"]}},{"t":"학습곡선과 검증곡선 읽기","q":[{"t":"choice","k":"U자 곡선","q":"규제 강도를 0에서 점점 키울 때 검증 오차가 그리는 전형적인 모양은?","ex":"적당한 규제는 분산을 줄여 검증 오차를 낮추지만, 지나치면 편향이 커져 다시 오차가 오른다. 그 최저점이 좋은 규제 강도다.","o":["처음에는 줄다가 어느 지점을 지나면 다시 커지는 U자","계속 줄어드는 단조 감소","계속 커지는 단조 증가","전 구간에서 일정"],"a":0},{"t":"choice","k":"조기종료 시점","q":"에폭이 진행되면서 훈련 손실은 계속 내려가는데 검증 손실이 어느 시점부터 다시 오르기 시작했다. 옳은 판단은?","ex":"검증 손실이 상승 전환한 뒤부터는 과적합 구간이다. 조기종료는 바로 이 최저점의 모델을 되살리는 기법이다.","o":["검증 손실이 최저였던 시점이 일반화가 가장 좋은 지점이다","훈련 손실이 최저인 마지막 에폭이 항상 최선이다","두 손실이 교차하는 지점을 골라야 한다","검증 손실이 오르면 학습률을 반드시 키워야 한다"],"a":0}],"th":{"sum":"예측 오차는 **편향**, **분산**, **줄일 수 없는 노이즈**로 나뉜다. 모델 복잡도를 올리면 편향은 줄고 분산은 커지는 **트레이드오프**가 생긴다.","body":[{"h":"편향과 분산의 정체","t":"**편향(bias)**은 모델이 너무 단순해 데이터의 참 관계를 담지 못해 생기는 체계적 오차다. **분산(variance)**은 훈련 데이터가 조금만 달라져도 학습 결과와 예측이 크게 흔들리는 정도다. 편향이 크면 과소적합으로, 분산이 크면 과적합으로 드러난다. 여기에 데이터 자체의 잡음에서 오는 **줄일 수 없는 오차**가 항상 더해지며, 이 값은 어떤 모델로도 제거할 수 없다."},{"h":"훈련·검증 오차로 진단하기","t":"훈련 오차와 검증 오차를 반드시 함께 본다. 둘 다 높으면 고편향(과소적합)이고, 훈련 오차만 낮은데 검증 오차와의 간격이 크게 벌어지면 고분산(과적합)이다. 고편향은 모델 용량을 키우거나 의미 있는 특성을 추가해 푼다. 고분산은 데이터를 더 모으거나 규제를 강화하고 불필요한 특성을 줄여서 푼다."},{"h":"학습곡선과 검증곡선","t":"**학습곡선**은 훈련 데이터 양에 따른 오차 변화를, **검증곡선**은 하이퍼파라미터 값에 따른 오차 변화를 그린다. 데이터를 늘려도 두 곡선이 높은 값에서 나란히 붙어 수렴하면 데이터가 아니라 모델이 문제인 고편향 상태다. 반대로 간격이 넓고 검증 곡선이 계속 내려가는 중이라면 데이터를 더 모으는 것이 유효하다."}],"code":{"c":"train 오차   val 오차   진단        처방\n  높음        높음     고편향     모델 용량↑, 특성 추가, 규제↓\n  낮음        높음     고분산     데이터↑, 규제↑, 특성 축소\n  낮음        낮음     양호       테스트 1회 평가 후 배포 검토\n\n총오차 = 편향² + 분산 + 노이즈(제거 불가)","cap":"훈련·검증 오차의 조합만으로 다음에 할 일이 정해진다"},"key":["편향↑ = 과소적합, 분산↑ = 과적합","복잡도를 올리면 편향은 줄고 분산은 커진다","노이즈(줄일 수 없는 오차)는 어떤 모델로도 0이 되지 않는다","훈련 오차 하나만 보고 판단하면 과적합을 놓친다"]}}]},{"t":"정규화로 과적합 잡기 (중급)","l":[{"t":"L1과 L2 규제","q":[{"t":"choice","k":"벌점 항","q":"릿지 회귀의 손실 함수에 추가되는 항은?","ex":"릿지는 L2 노름의 제곱, 즉 계수 제곱합에 α를 곱한 벌점을 더한다.","o":["계수의 제곱합에 비례하는 벌점","계수의 절댓값 합에 비례하는 벌점","잔차의 절댓값 합","특성 개수의 로그"],"a":0},{"t":"choice","k":"α 증가","q":"규제 강도 α를 키우면 편향과 분산은 어떻게 변하는가?","ex":"규제는 모델을 단순한 쪽으로 밀어붙이는 장치라 분산을 희생 대가로 편향을 늘린다.","o":["편향이 커지고 분산이 줄어든다","편향과 분산이 함께 커진다","편향이 줄고 분산이 커진다","둘 다 변하지 않는다"],"a":0}],"th":{"sum":"정규화(규제)는 손실에 **벌점**을 더해 모델이 지나치게 커지는 것을 막는다. **L1은 계수를 0으로 만들어 희소성**을, **L2는 계수를 전체적으로 축소**한다.","body":[{"h":"L1과 L2의 차이","t":"**L2(릿지)**는 계수의 제곱합에 벌점을 걸어 계수를 0에 가깝게 고르게 축소하지만 정확히 0으로 만들지는 않는다. **L1(라쏘)**는 절댓값 합에 벌점을 걸어 일부 계수를 정확히 0으로 만들어 자동 특성 선택 효과를 낸다. 그래서 특성이 아주 많고 그중 소수만 유효할 것 같으면 L1, 상관이 높은 특성이 많아 계수를 안정화하고 싶으면 L2가 잘 맞는다. 둘을 섞은 것이 엘라스틱넷이다."},{"h":"규제 강도 조절","t":"벌점 계수 α(또는 λ)를 키우면 계수가 더 강하게 눌려 **분산은 줄고 편향은 커진다**. 지나치게 키우면 과소적합이 된다. 사이킷런의 로지스틱 회귀와 SVM은 α 대신 C를 쓰는데 C는 규제 강도의 역수라서 **C가 작을수록 규제가 강하다**. 적정값은 훈련 오차가 아니라 교차검증 성능으로 고른다. 벌점이 계수 크기에 걸리므로 특성 스케일링을 먼저 해야 공정하다."},{"h":"드롭아웃과 조기종료","t":"신경망에서 **드롭아웃**은 학습 중 각 뉴런을 확률 p로 무작위로 꺼서 특정 뉴런 조합에만 의존하는 공적응을 막는다. 중요한 점은 **드롭아웃이 학습 시에만 동작하고 추론 시에는 비활성화**되어 모든 뉴런을 쓴다는 것이다. **조기종료**는 검증 손실이 더 이상 개선되지 않을 때 학습을 멈춰 과적합 구간에 들어가기 전에 모델을 확정하는 기법이다."}],"code":{"c":"L2 (Ridge)      : loss + α·Σ w²        → 계수 고르게 축소, 정확히 0은 아님\nL1 (Lasso)      : loss + α·Σ |w|       → 일부 계수 정확히 0 (희소)\nElasticNet      : loss + α(r·Σ|w| + (1-r)·Σw²)\n\nsklearn C 파라미터: C = 1/α  →  C가 작을수록 규제 강함\nDropout : 학습 시 확률 p로 뉴런 off / 추론 시 전부 on","cap":"벌점의 모양이 계수의 운명을 가른다"},"key":["L1 = 희소성(특성 선택), L2 = 축소(안정화)","α를 키우면 분산↓ 편향↑, 너무 키우면 과소적합","C는 α의 역수라 C가 작을수록 규제가 강하다","드롭아웃은 학습 시에만 적용되고 추론 시에는 꺼진다"]}},{"t":"규제 강도 튜닝","q":[{"t":"choice","k":"C 파라미터","q":"사이킷런 LogisticRegression에서 C 값을 작게 하면 어떻게 되는가?","ex":"C는 규제 강도의 역수(C = 1/α)다. C를 줄일수록 벌점이 커져 모델이 단순해진다.","o":["규제가 강해진다","규제가 약해진다","학습률이 커진다","특성 개수가 늘어난다"],"a":0},{"t":"choice","k":"규제와 데이터량","q":"훈련 데이터 양이 크게 늘어났을 때 필요한 규제 강도는 일반적으로 어떻게 변하는가?","ex":"데이터가 많아지면 분산이 자연히 줄기 때문에 규제로 눌러야 할 양도 줄어든다. 그래도 최적값은 교차검증으로 다시 확인한다.","o":["과적합 위험이 줄어들어 더 약한 규제로도 충분해지는 경향이 있다","데이터가 많을수록 더 강한 규제가 반드시 필요하다","데이터 양과 규제 강도는 전혀 관련이 없다","데이터가 많아지면 규제를 항상 최대로 해야 한다"],"a":0},{"t":"input","k":"엘라스틱넷","q":"L1 벌점과 L2 벌점을 함께 사용하는 선형 회귀 규제 기법의 이름은? (한글 또는 영문)","ex":"엘라스틱넷은 L1의 희소성과 L2의 안정성을 혼합 비율 r로 조절해 함께 얻는다.","a":["엘라스틱넷","엘라스틱 넷","일래스틱넷","elastic net","elasticnet"]}],"th":{"sum":"정규화(규제)는 손실에 **벌점**을 더해 모델이 지나치게 커지는 것을 막는다. **L1은 계수를 0으로 만들어 희소성**을, **L2는 계수를 전체적으로 축소**한다.","body":[{"h":"L1과 L2의 차이","t":"**L2(릿지)**는 계수의 제곱합에 벌점을 걸어 계수를 0에 가깝게 고르게 축소하지만 정확히 0으로 만들지는 않는다. **L1(라쏘)**는 절댓값 합에 벌점을 걸어 일부 계수를 정확히 0으로 만들어 자동 특성 선택 효과를 낸다. 그래서 특성이 아주 많고 그중 소수만 유효할 것 같으면 L1, 상관이 높은 특성이 많아 계수를 안정화하고 싶으면 L2가 잘 맞는다. 둘을 섞은 것이 엘라스틱넷이다."},{"h":"규제 강도 조절","t":"벌점 계수 α(또는 λ)를 키우면 계수가 더 강하게 눌려 **분산은 줄고 편향은 커진다**. 지나치게 키우면 과소적합이 된다. 사이킷런의 로지스틱 회귀와 SVM은 α 대신 C를 쓰는데 C는 규제 강도의 역수라서 **C가 작을수록 규제가 강하다**. 적정값은 훈련 오차가 아니라 교차검증 성능으로 고른다. 벌점이 계수 크기에 걸리므로 특성 스케일링을 먼저 해야 공정하다."},{"h":"드롭아웃과 조기종료","t":"신경망에서 **드롭아웃**은 학습 중 각 뉴런을 확률 p로 무작위로 꺼서 특정 뉴런 조합에만 의존하는 공적응을 막는다. 중요한 점은 **드롭아웃이 학습 시에만 동작하고 추론 시에는 비활성화**되어 모든 뉴런을 쓴다는 것이다. **조기종료**는 검증 손실이 더 이상 개선되지 않을 때 학습을 멈춰 과적합 구간에 들어가기 전에 모델을 확정하는 기법이다."}],"code":{"c":"L2 (Ridge)      : loss + α·Σ w²        → 계수 고르게 축소, 정확히 0은 아님\nL1 (Lasso)      : loss + α·Σ |w|       → 일부 계수 정확히 0 (희소)\nElasticNet      : loss + α(r·Σ|w| + (1-r)·Σw²)\n\nsklearn C 파라미터: C = 1/α  →  C가 작을수록 규제 강함\nDropout : 학습 시 확률 p로 뉴런 off / 추론 시 전부 on","cap":"벌점의 모양이 계수의 운명을 가른다"},"key":["L1 = 희소성(특성 선택), L2 = 축소(안정화)","α를 키우면 분산↓ 편향↑, 너무 키우면 과소적합","C는 α의 역수라 C가 작을수록 규제가 강하다","드롭아웃은 학습 시에만 적용되고 추론 시에는 꺼진다"]}},{"t":"드롭아웃과 조기종료","q":[{"t":"choice","k":"드롭아웃 추론","q":"드롭아웃은 추론(예측) 단계에서 어떻게 동작하는가?","ex":"드롭아웃은 학습 전용 규제다. 추론 시 뉴런을 끄면 예측이 매번 달라지고 성능도 떨어진다. 프레임워크의 eval 모드가 이를 자동으로 꺼 준다.","o":["비활성화되어 모든 뉴런을 사용한다","학습 때와 동일한 확률로 계속 뉴런을 끈다","추론 단계에서만 적용된다","가중치를 매번 무작위로 초기화한다"],"a":0},{"t":"choice","k":"조기종료 기준","q":"조기종료(early stopping)가 학습을 멈추는 기준은?","ex":"기준은 검증 세트여야 한다. 테스트 세트를 종료 기준으로 쓰면 테스트가 사실상 검증 세트가 되어 최종 평가가 낙관적으로 왜곡된다.","o":["검증 손실이 일정 기간 개선되지 않으면 멈춘다","훈련 손실이 0에 도달하면 멈춘다","미리 정한 에폭 수를 무조건 다 채운 뒤 멈춘다","테스트 손실이 오르면 멈춘다"],"a":0},{"t":"choice","k":"오개념 판별","q":"규제 기법에 대한 설명 중 옳지 않은 것은?","ex":"드롭아웃은 추론 시 비활성화되는 것이 정상 동작이다. 나머지 세 설명은 모두 맞다.","o":["드롭아웃은 추론 단계에서도 켜 두어야 정확도가 올라간다","L1 규제는 희소한 계수 벡터를 만든다","L2 규제는 계수를 0에 가깝게 축소한다","조기종료는 검증 성능을 기준으로 학습을 중단한다"],"a":0}],"th":{"sum":"정규화(규제)는 손실에 **벌점**을 더해 모델이 지나치게 커지는 것을 막는다. **L1은 계수를 0으로 만들어 희소성**을, **L2는 계수를 전체적으로 축소**한다.","body":[{"h":"L1과 L2의 차이","t":"**L2(릿지)**는 계수의 제곱합에 벌점을 걸어 계수를 0에 가깝게 고르게 축소하지만 정확히 0으로 만들지는 않는다. **L1(라쏘)**는 절댓값 합에 벌점을 걸어 일부 계수를 정확히 0으로 만들어 자동 특성 선택 효과를 낸다. 그래서 특성이 아주 많고 그중 소수만 유효할 것 같으면 L1, 상관이 높은 특성이 많아 계수를 안정화하고 싶으면 L2가 잘 맞는다. 둘을 섞은 것이 엘라스틱넷이다."},{"h":"규제 강도 조절","t":"벌점 계수 α(또는 λ)를 키우면 계수가 더 강하게 눌려 **분산은 줄고 편향은 커진다**. 지나치게 키우면 과소적합이 된다. 사이킷런의 로지스틱 회귀와 SVM은 α 대신 C를 쓰는데 C는 규제 강도의 역수라서 **C가 작을수록 규제가 강하다**. 적정값은 훈련 오차가 아니라 교차검증 성능으로 고른다. 벌점이 계수 크기에 걸리므로 특성 스케일링을 먼저 해야 공정하다."},{"h":"드롭아웃과 조기종료","t":"신경망에서 **드롭아웃**은 학습 중 각 뉴런을 확률 p로 무작위로 꺼서 특정 뉴런 조합에만 의존하는 공적응을 막는다. 중요한 점은 **드롭아웃이 학습 시에만 동작하고 추론 시에는 비활성화**되어 모든 뉴런을 쓴다는 것이다. **조기종료**는 검증 손실이 더 이상 개선되지 않을 때 학습을 멈춰 과적합 구간에 들어가기 전에 모델을 확정하는 기법이다."}],"code":{"c":"L2 (Ridge)      : loss + α·Σ w²        → 계수 고르게 축소, 정확히 0은 아님\nL1 (Lasso)      : loss + α·Σ |w|       → 일부 계수 정확히 0 (희소)\nElasticNet      : loss + α(r·Σ|w| + (1-r)·Σw²)\n\nsklearn C 파라미터: C = 1/α  →  C가 작을수록 규제 강함\nDropout : 학습 시 확률 p로 뉴런 off / 추론 시 전부 on","cap":"벌점의 모양이 계수의 운명을 가른다"},"key":["L1 = 희소성(특성 선택), L2 = 축소(안정화)","α를 키우면 분산↓ 편향↑, 너무 키우면 과소적합","C는 α의 역수라 C가 작을수록 규제가 강하다","드롭아웃은 학습 시에만 적용되고 추론 시에는 꺼진다"]}}]},{"t":"특성 공학과 데이터 누수 (심화)","l":[{"t":"특성 공학 기초","q":[{"t":"choice","k":"로그 변환","q":"오른쪽으로 크게 치우친 결제 금액 특성에 흔히 적용하는 변환은?","ex":"로그 변환은 큰 값의 영향력을 줄여 선형 모델이 관계를 잡기 쉽게 만든다. 0이 있으면 log1p를 쓴다.","o":["로그 변환으로 치우침을 완화한다","모든 값을 제곱한다","값의 부호를 뒤집는다","무작위 노이즈를 더한다"],"a":0},{"t":"choice","k":"상호작용","q":"상호작용 특성(interaction feature)을 만드는 예로 가장 적절한 것은?","ex":"두 특성이 함께 작용할 때만 드러나는 관계를 선형 모델에도 알려줄 수 있다. 레이블을 특성으로 넣는 것은 명백한 누수다.","o":["면적과 방 개수의 비율처럼 두 특성을 조합한 새 컬럼을 만든다","정답 레이블을 그대로 특성으로 추가한다","행을 무작위로 복제한다","특성 값을 무작위로 섞는다"],"a":0}],"th":{"sum":"특성 공학은 원자료를 모델이 쓸 수 있는 신호로 바꾸는 작업이다. 이때 **미래 정보나 정답이 새어 들어가는 데이터 누수**를 막는 것이 성능보다 먼저다.","body":[{"h":"특성 공학과 인코딩","t":"순서 의미가 없는 범주형은 **원-핫 인코딩**으로, 순서가 있는 범주형은 순서를 보존하는 정수로 바꾼다. 도시 이름에 1, 2, 3을 부여하면 모델이 존재하지 않는 크기 관계를 배운다. 치우친 금액 분포에는 로그 변환을, 날짜에는 요일·월·공휴일 여부 같은 파생 특성을 만든다. 범주 수가 수만 개인 ID형 특성을 원-핫하면 차원이 폭발하므로 빈도 기반 묶음이나 임베딩을 고려한다."},{"h":"스케일링","t":"**표준화(StandardScaler)**는 평균 0·표준편차 1로, **정규화(MinMaxScaler)**는 지정 범위(보통 0~1)로 값을 옮긴다. KNN·SVM·로지스틱 회귀·신경망처럼 거리나 경사하강법에 기대는 모델은 스케일에 민감하지만, 결정트리와 랜덤포레스트·부스팅 트리는 분할이 값의 순서에만 의존해 스케일 영향이 사실상 없다. 이상치가 많으면 MinMax는 범위가 이상치에 지배되므로 RobustScaler가 낫다."},{"h":"데이터 누수 차단","t":"스케일러·결측치 대치·인코딩의 통계는 **훈련 폴드에서만 fit**하고 검증·테스트에는 transform만 적용한다. 전체 데이터로 먼저 fit하면 검증 점수가 부풀려진다. 사건 이후에만 생기는 컬럼(해지 처리 코드 등), 같은 사용자의 기록이 훈련과 테스트에 쪼개져 들어가는 **그룹 누수**도 흔한 함정이다. **Pipeline**으로 전처리와 모델을 묶으면 교차검증에서 폴드별로 자동 fit되어 안전하다."}],"code":{"c":"# 누수가 생기는 순서 (잘못)\nscaler.fit(X_all)\nX = scaler.transform(X_all)\nX_tr, X_te = split(X)      # 테스트 통계가 이미 섞임\n\n# 올바른 순서\nX_tr, X_te = split(X_all)\nscaler.fit(X_tr)           # fit은 훈련에서만\nX_tr = scaler.transform(X_tr)\nX_te = scaler.transform(X_te)\n\n# 더 안전한 방법\nPipeline([('sc', StandardScaler()), ('clf', LogisticRegression())])","cap":"fit은 훈련에서만, transform은 어디에서나"},"key":["fit은 훈련 폴드에서만, 검증·테스트는 transform만","트리 계열은 스케일링이 거의 불필요, 거리·경사 기반 모델은 필수","사후 정보·그룹 중복은 대표적인 누수 경로","검증 점수가 비현실적으로 높으면 먼저 누수를 의심한다"]}},{"t":"스케일링과 파이프라인","q":[{"t":"choice","k":"표준화 결과","q":"StandardScaler를 적용한 특성의 통계는 대략 어떻게 되는가?","ex":"각 값에서 평균을 빼고 표준편차로 나누는 z-점수 변환이다. 0~1 범위로 만드는 쪽은 MinMaxScaler다.","o":["평균 0, 표준편차 1","최솟값 0, 최댓값 1","평균 1, 분산 0","중앙값 0, 사분위범위 1"],"a":0},{"t":"choice","k":"테스트 처리","q":"테스트 세트에 스케일러를 적용하는 올바른 방법은?","ex":"테스트로 fit하면 그 분포 정보가 새어 들어가고, 스케일링을 생략하면 훈련 때와 다른 입력 분포가 들어가 성능이 무너진다.","o":["훈련 데이터로 학습한 스케일러로 transform만 수행한다","테스트 세트로 다시 fit한 뒤 transform한다","훈련과 테스트를 합쳐 fit한 뒤 transform한다","테스트 세트에는 스케일링을 적용하지 않는다"],"a":0},{"t":"input","k":"표준화 용어","q":"각 특성을 평균 0, 표준편차 1로 변환하는 전처리를 부르는 한글 용어는? (3글자)","ex":"표준화(standardization)는 z-점수 변환이라고도 부른다.","a":["표준화","standardization","z-score","z점수"]}],"th":{"sum":"특성 공학은 원자료를 모델이 쓸 수 있는 신호로 바꾸는 작업이다. 이때 **미래 정보나 정답이 새어 들어가는 데이터 누수**를 막는 것이 성능보다 먼저다.","body":[{"h":"특성 공학과 인코딩","t":"순서 의미가 없는 범주형은 **원-핫 인코딩**으로, 순서가 있는 범주형은 순서를 보존하는 정수로 바꾼다. 도시 이름에 1, 2, 3을 부여하면 모델이 존재하지 않는 크기 관계를 배운다. 치우친 금액 분포에는 로그 변환을, 날짜에는 요일·월·공휴일 여부 같은 파생 특성을 만든다. 범주 수가 수만 개인 ID형 특성을 원-핫하면 차원이 폭발하므로 빈도 기반 묶음이나 임베딩을 고려한다."},{"h":"스케일링","t":"**표준화(StandardScaler)**는 평균 0·표준편차 1로, **정규화(MinMaxScaler)**는 지정 범위(보통 0~1)로 값을 옮긴다. KNN·SVM·로지스틱 회귀·신경망처럼 거리나 경사하강법에 기대는 모델은 스케일에 민감하지만, 결정트리와 랜덤포레스트·부스팅 트리는 분할이 값의 순서에만 의존해 스케일 영향이 사실상 없다. 이상치가 많으면 MinMax는 범위가 이상치에 지배되므로 RobustScaler가 낫다."},{"h":"데이터 누수 차단","t":"스케일러·결측치 대치·인코딩의 통계는 **훈련 폴드에서만 fit**하고 검증·테스트에는 transform만 적용한다. 전체 데이터로 먼저 fit하면 검증 점수가 부풀려진다. 사건 이후에만 생기는 컬럼(해지 처리 코드 등), 같은 사용자의 기록이 훈련과 테스트에 쪼개져 들어가는 **그룹 누수**도 흔한 함정이다. **Pipeline**으로 전처리와 모델을 묶으면 교차검증에서 폴드별로 자동 fit되어 안전하다."}],"code":{"c":"# 누수가 생기는 순서 (잘못)\nscaler.fit(X_all)\nX = scaler.transform(X_all)\nX_tr, X_te = split(X)      # 테스트 통계가 이미 섞임\n\n# 올바른 순서\nX_tr, X_te = split(X_all)\nscaler.fit(X_tr)           # fit은 훈련에서만\nX_tr = scaler.transform(X_tr)\nX_te = scaler.transform(X_te)\n\n# 더 안전한 방법\nPipeline([('sc', StandardScaler()), ('clf', LogisticRegression())])","cap":"fit은 훈련에서만, transform은 어디에서나"},"key":["fit은 훈련 폴드에서만, 검증·테스트는 transform만","트리 계열은 스케일링이 거의 불필요, 거리·경사 기반 모델은 필수","사후 정보·그룹 중복은 대표적인 누수 경로","검증 점수가 비현실적으로 높으면 먼저 누수를 의심한다"]}},{"t":"데이터 누수 잡아내기","q":[{"t":"choice","k":"전처리 순서","q":"다음 중 데이터 누수를 일으키는 절차는?","ex":"전체 데이터로 fit하면 테스트의 평균·표준편차가 훈련 과정에 스며든다. 그 결과 검증 점수가 실제보다 좋게 나온다.","o":["전체 데이터로 스케일러를 fit한 뒤 훈련/테스트로 분할한다","훈련 데이터로만 fit하고 테스트에는 transform만 한다","Pipeline으로 묶어 교차검증한다","결측치 대치 평균을 훈련 폴드에서만 계산한다"],"a":0},{"t":"choice","k":"의심 신호","q":"검증 정확도가 0.999처럼 비정상적으로 높게 나왔을 때 가장 먼저 해야 할 일은?","ex":"현실 문제에서 거의 완벽한 성능은 대개 누수의 신호다. 특성 중요도 상위 항목이 타깃과 직결되는 컬럼인지부터 확인한다.","o":["데이터 누수 가능성부터 점검한다","곧바로 프로덕션에 배포한다","모델 복잡도를 더 높인다","테스트 세트를 훈련 데이터에 합친다"],"a":0},{"t":"input","k":"그룹 분할","q":"같은 사용자나 환자의 기록이 훈련과 검증에 나뉘어 들어가지 않도록 그룹 단위로 나누는 사이킷런 교차검증 클래스의 이름은? (영문)","ex":"GroupKFold는 지정한 그룹 ID가 여러 폴드에 걸치지 않도록 분할해 그룹 누수를 막는다.","a":["GroupKFold","groupkfold","group kfold","group k-fold"]}],"th":{"sum":"특성 공학은 원자료를 모델이 쓸 수 있는 신호로 바꾸는 작업이다. 이때 **미래 정보나 정답이 새어 들어가는 데이터 누수**를 막는 것이 성능보다 먼저다.","body":[{"h":"특성 공학과 인코딩","t":"순서 의미가 없는 범주형은 **원-핫 인코딩**으로, 순서가 있는 범주형은 순서를 보존하는 정수로 바꾼다. 도시 이름에 1, 2, 3을 부여하면 모델이 존재하지 않는 크기 관계를 배운다. 치우친 금액 분포에는 로그 변환을, 날짜에는 요일·월·공휴일 여부 같은 파생 특성을 만든다. 범주 수가 수만 개인 ID형 특성을 원-핫하면 차원이 폭발하므로 빈도 기반 묶음이나 임베딩을 고려한다."},{"h":"스케일링","t":"**표준화(StandardScaler)**는 평균 0·표준편차 1로, **정규화(MinMaxScaler)**는 지정 범위(보통 0~1)로 값을 옮긴다. KNN·SVM·로지스틱 회귀·신경망처럼 거리나 경사하강법에 기대는 모델은 스케일에 민감하지만, 결정트리와 랜덤포레스트·부스팅 트리는 분할이 값의 순서에만 의존해 스케일 영향이 사실상 없다. 이상치가 많으면 MinMax는 범위가 이상치에 지배되므로 RobustScaler가 낫다."},{"h":"데이터 누수 차단","t":"스케일러·결측치 대치·인코딩의 통계는 **훈련 폴드에서만 fit**하고 검증·테스트에는 transform만 적용한다. 전체 데이터로 먼저 fit하면 검증 점수가 부풀려진다. 사건 이후에만 생기는 컬럼(해지 처리 코드 등), 같은 사용자의 기록이 훈련과 테스트에 쪼개져 들어가는 **그룹 누수**도 흔한 함정이다. **Pipeline**으로 전처리와 모델을 묶으면 교차검증에서 폴드별로 자동 fit되어 안전하다."}],"code":{"c":"# 누수가 생기는 순서 (잘못)\nscaler.fit(X_all)\nX = scaler.transform(X_all)\nX_tr, X_te = split(X)      # 테스트 통계가 이미 섞임\n\n# 올바른 순서\nX_tr, X_te = split(X_all)\nscaler.fit(X_tr)           # fit은 훈련에서만\nX_tr = scaler.transform(X_tr)\nX_te = scaler.transform(X_te)\n\n# 더 안전한 방법\nPipeline([('sc', StandardScaler()), ('clf', LogisticRegression())])","cap":"fit은 훈련에서만, transform은 어디에서나"},"key":["fit은 훈련 폴드에서만, 검증·테스트는 transform만","트리 계열은 스케일링이 거의 불필요, 거리·경사 기반 모델은 필수","사후 정보·그룹 중복은 대표적인 누수 경로","검증 점수가 비현실적으로 높으면 먼저 누수를 의심한다"]}}]},{"t":"앙상블과 하이퍼파라미터 탐색 (심화)","l":[{"t":"배깅과 랜덤포레스트","q":[{"t":"choice","k":"배깅 목적","q":"배깅(bagging)이 주로 줄이는 오차 성분은?","ex":"서로 다른 표본으로 학습한 모델들의 예측을 평균내면 개별 모델의 흔들림이 상쇄되어 분산이 줄어든다.","o":["분산","편향","줄일 수 없는 노이즈","측정 오차"],"a":0},{"t":"choice","k":"부트스트랩","q":"배깅에서 각 개별 모델이 학습에 사용하는 데이터는?","ex":"복원추출이므로 어떤 샘플은 여러 번 뽑히고 어떤 샘플은 한 번도 뽑히지 않는다. 이 차이가 모델 간 다양성을 만든다.","o":["원본에서 복원추출로 만든 부트스트랩 표본","항상 원본 전체 데이터 그대로","테스트 세트","레이블을 제거한 데이터"],"a":0}],"th":{"sum":"**배깅은 분산을 줄이고 부스팅은 편향을 줄인다.** 어떤 오차를 줄이려는지에 따라 앙상블 전략이 갈리며, 하이퍼파라미터는 검증으로 탐색한다.","body":[{"h":"배깅과 랜덤포레스트","t":"**배깅(bagging)**은 원본에서 복원추출한 부트스트랩 표본으로 여러 모델을 **병렬** 학습한 뒤 평균이나 다수결로 합친다. 서로 다른 오차가 상쇄되면서 **분산이 줄어든다**. 랜덤포레스트는 여기에 더해 각 분할에서 특성의 부분집합만 후보로 삼아 트리 간 상관을 낮춘다. 부트스트랩에서 뽑히지 않은 샘플로 성능을 추정하는 OOB 방식도 쓸 수 있다."},{"h":"부스팅","t":"**부스팅(boosting)**은 앞선 모델이 틀린 부분에 집중하는 약한 학습기를 **순차적으로** 쌓아 **편향을 줄인다**. 보통 깊이가 얕은 트리를 기본 학습기로 쓰고, 학습률을 낮추면 그만큼 트리 수를 늘려야 한다. 성능은 뛰어나지만 트리를 지나치게 많이 쌓으면 노이즈까지 학습해 과적합되고, 이상치와 잘못된 레이블에 민감하다. 부스팅이 항상 배깅보다 나은 것은 아니다."},{"h":"하이퍼파라미터 탐색","t":"**그리드 탐색**은 격자의 모든 조합을 시도해 차원이 늘면 비용이 폭증한다. **랜덤 탐색**은 같은 예산에서 중요한 하이퍼파라미터의 값을 더 다양하게 시험해 보통 더 효율적이다. **베이지안 최적화**는 이전 결과를 모델링해 다음 후보를 고른다. 어느 방식이든 평가는 검증 세트나 교차검증으로 하고, 탐색과 평가를 분리하려면 **중첩 교차검증**을 쓴다."}],"code":{"c":"배깅   : 독립 모델 여러 개 → 평균/투표   (분산↓)  예) 랜덤포레스트\n부스팅 : 이전 오차를 보완하며 순차 학습  (편향↓)  예) GBM, XGBoost\n스태킹 : 여러 모델의 예측을 메타모델의 입력으로\n\n탐색 : Grid(전수, 조합 폭증) / Random(예산 대비 효율↑) / Bayesian(적응적)\n학습률↓ 이면 트리 수↑ 로 보상","cap":"줄이려는 오차가 무엇인지가 앙상블 선택의 기준이다"},"key":["배깅=병렬·분산 감소, 부스팅=순차·편향 감소","랜덤포레스트는 특성 부분집합으로 트리 간 상관을 낮춘다","랜덤 탐색은 같은 예산에서 그리드보다 효율적인 경우가 많다","탐색은 검증으로, 테스트는 최종 확인 1회만"]}},{"t":"부스팅 이해하기","q":[{"t":"choice","k":"약한 학습기","q":"그래디언트 부스팅에서 기본 학습기로 흔히 쓰는 것은?","ex":"각 단계에서 조금씩만 개선해야 안정적이므로 편향이 큰 얕은 트리를 여러 개 쌓는다.","o":["깊이를 얕게 제한한 결정트리","깊이 제한이 없는 완전 성장 트리","선형 SVM 한 개","KNN 분류기"],"a":0},{"t":"choice","k":"학습률","q":"부스팅의 학습률(learning rate)을 낮추면 일반적으로 무엇을 함께 조정해야 하는가?","ex":"학습률과 트리 수는 서로 맞물린 하이퍼파라미터다. 낮은 학습률에 많은 트리 조합이 보통 더 안정적인 성능을 낸다.","o":["트리 개수를 늘려야 비슷한 성능에 도달한다","트리 개수를 줄여야 한다","특성 개수를 늘려야 한다","아무것도 조정할 필요가 없다"],"a":0},{"t":"choice","k":"스태킹","q":"스태킹(stacking) 앙상블의 구조로 옳은 것은?","ex":"메타모델 학습에 쓰는 예측값은 교차검증으로 만든 out-of-fold 예측이어야 누수를 피할 수 있다.","o":["여러 기반 모델의 예측값을 입력으로 받는 메타모델을 따로 학습한다","기반 모델들의 예측을 항상 단순 평균한다","가장 성능이 좋은 모델 하나만 남긴다","모델을 순차적으로 쌓아 잔차를 학습한다"],"a":0}],"th":{"sum":"**배깅은 분산을 줄이고 부스팅은 편향을 줄인다.** 어떤 오차를 줄이려는지에 따라 앙상블 전략이 갈리며, 하이퍼파라미터는 검증으로 탐색한다.","body":[{"h":"배깅과 랜덤포레스트","t":"**배깅(bagging)**은 원본에서 복원추출한 부트스트랩 표본으로 여러 모델을 **병렬** 학습한 뒤 평균이나 다수결로 합친다. 서로 다른 오차가 상쇄되면서 **분산이 줄어든다**. 랜덤포레스트는 여기에 더해 각 분할에서 특성의 부분집합만 후보로 삼아 트리 간 상관을 낮춘다. 부트스트랩에서 뽑히지 않은 샘플로 성능을 추정하는 OOB 방식도 쓸 수 있다."},{"h":"부스팅","t":"**부스팅(boosting)**은 앞선 모델이 틀린 부분에 집중하는 약한 학습기를 **순차적으로** 쌓아 **편향을 줄인다**. 보통 깊이가 얕은 트리를 기본 학습기로 쓰고, 학습률을 낮추면 그만큼 트리 수를 늘려야 한다. 성능은 뛰어나지만 트리를 지나치게 많이 쌓으면 노이즈까지 학습해 과적합되고, 이상치와 잘못된 레이블에 민감하다. 부스팅이 항상 배깅보다 나은 것은 아니다."},{"h":"하이퍼파라미터 탐색","t":"**그리드 탐색**은 격자의 모든 조합을 시도해 차원이 늘면 비용이 폭증한다. **랜덤 탐색**은 같은 예산에서 중요한 하이퍼파라미터의 값을 더 다양하게 시험해 보통 더 효율적이다. **베이지안 최적화**는 이전 결과를 모델링해 다음 후보를 고른다. 어느 방식이든 평가는 검증 세트나 교차검증으로 하고, 탐색과 평가를 분리하려면 **중첩 교차검증**을 쓴다."}],"code":{"c":"배깅   : 독립 모델 여러 개 → 평균/투표   (분산↓)  예) 랜덤포레스트\n부스팅 : 이전 오차를 보완하며 순차 학습  (편향↓)  예) GBM, XGBoost\n스태킹 : 여러 모델의 예측을 메타모델의 입력으로\n\n탐색 : Grid(전수, 조합 폭증) / Random(예산 대비 효율↑) / Bayesian(적응적)\n학습률↓ 이면 트리 수↑ 로 보상","cap":"줄이려는 오차가 무엇인지가 앙상블 선택의 기준이다"},"key":["배깅=병렬·분산 감소, 부스팅=순차·편향 감소","랜덤포레스트는 특성 부분집합으로 트리 간 상관을 낮춘다","랜덤 탐색은 같은 예산에서 그리드보다 효율적인 경우가 많다","탐색은 검증으로, 테스트는 최종 확인 1회만"]}},{"t":"하이퍼파라미터 탐색 전략","q":[{"t":"choice","k":"탐색 척도","q":"학습률이나 규제 강도처럼 자릿수 규모가 중요한 하이퍼파라미터는 어떤 척도로 탐색하는 것이 효율적인가?","ex":"0.001과 0.01의 차이가 0.1과 0.11의 차이보다 훨씬 크므로, 자릿수 단위로 훑은 뒤 유망한 구간을 좁혀 들어간다.","o":["로그 척도(예: 0.0001, 0.001, 0.01, 0.1)","좁은 구간의 등간격 선형 척도","정수 값만","0과 1 두 값만"],"a":0},{"t":"input","k":"베이지안","q":"이전 시도 결과를 확률 모델로 학습해 다음에 시도할 하이퍼파라미터 후보를 고르는 탐색 기법의 이름은? (한글 또는 영문)","ex":"베이지안 최적화는 평가 비용이 비쌀 때 적은 시도로 좋은 조합을 찾는 데 유리하다. Optuna 같은 도구가 이를 지원한다.","a":["베이지안 최적화","베이지안최적화","bayesian optimization","베이즈 최적화"]}],"th":{"sum":"**배깅은 분산을 줄이고 부스팅은 편향을 줄인다.** 어떤 오차를 줄이려는지에 따라 앙상블 전략이 갈리며, 하이퍼파라미터는 검증으로 탐색한다.","body":[{"h":"배깅과 랜덤포레스트","t":"**배깅(bagging)**은 원본에서 복원추출한 부트스트랩 표본으로 여러 모델을 **병렬** 학습한 뒤 평균이나 다수결로 합친다. 서로 다른 오차가 상쇄되면서 **분산이 줄어든다**. 랜덤포레스트는 여기에 더해 각 분할에서 특성의 부분집합만 후보로 삼아 트리 간 상관을 낮춘다. 부트스트랩에서 뽑히지 않은 샘플로 성능을 추정하는 OOB 방식도 쓸 수 있다."},{"h":"부스팅","t":"**부스팅(boosting)**은 앞선 모델이 틀린 부분에 집중하는 약한 학습기를 **순차적으로** 쌓아 **편향을 줄인다**. 보통 깊이가 얕은 트리를 기본 학습기로 쓰고, 학습률을 낮추면 그만큼 트리 수를 늘려야 한다. 성능은 뛰어나지만 트리를 지나치게 많이 쌓으면 노이즈까지 학습해 과적합되고, 이상치와 잘못된 레이블에 민감하다. 부스팅이 항상 배깅보다 나은 것은 아니다."},{"h":"하이퍼파라미터 탐색","t":"**그리드 탐색**은 격자의 모든 조합을 시도해 차원이 늘면 비용이 폭증한다. **랜덤 탐색**은 같은 예산에서 중요한 하이퍼파라미터의 값을 더 다양하게 시험해 보통 더 효율적이다. **베이지안 최적화**는 이전 결과를 모델링해 다음 후보를 고른다. 어느 방식이든 평가는 검증 세트나 교차검증으로 하고, 탐색과 평가를 분리하려면 **중첩 교차검증**을 쓴다."}],"code":{"c":"배깅   : 독립 모델 여러 개 → 평균/투표   (분산↓)  예) 랜덤포레스트\n부스팅 : 이전 오차를 보완하며 순차 학습  (편향↓)  예) GBM, XGBoost\n스태킹 : 여러 모델의 예측을 메타모델의 입력으로\n\n탐색 : Grid(전수, 조합 폭증) / Random(예산 대비 효율↑) / Bayesian(적응적)\n학습률↓ 이면 트리 수↑ 로 보상","cap":"줄이려는 오차가 무엇인지가 앙상블 선택의 기준이다"},"key":["배깅=병렬·분산 감소, 부스팅=순차·편향 감소","랜덤포레스트는 특성 부분집합으로 트리 간 상관을 낮춘다","랜덤 탐색은 같은 예산에서 그리드보다 효율적인 경우가 많다","탐색은 검증으로, 테스트는 최종 확인 1회만"]}}]},{"t":"코드 리뷰 — 결함 찾기","l":[{"t":"코드 리뷰 I","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"scaler = StandardScaler().fit(X)\nXs = scaler.transform(X)\nXtr, Xte, ytr, yte = train_test_split(Xs, y, test_size=0.2)\nmodel.fit(Xtr, ytr)\nprint(model.score(Xte, yte))","items":[{"txt":"전체 데이터로 스케일러를 학습한 뒤 분할했다. 테스트 세트의 평균·표준편차가 학습에 흘러들어 성능이 부풀려진다(데이터 누수).","bad":true},{"txt":"전처리와 모델을 Pipeline 으로 묶지 않아, 교차검증을 하면 같은 누수가 폴드마다 반복된다.","bad":true},{"txt":"random_state 를 지정하지 않아 실행마다 분할이 달라지고 결과를 재현할 수 없다.","bad":true},{"txt":"StandardScaler 는 각 열을 독립적으로 처리하므로 분할 순서와 무관하게 누수가 없다.","bad":false},{"txt":"test_size=0.2 는 너무 작아 평가 신뢰도가 낮은 것이 핵심 결함이다.","bad":false},{"txt":"model.score 는 정확도만 반환하므로 회귀 문제에서는 오류가 난다.","bad":false}],"ex":"결함 3가지: (1) 분할 전 스케일링 — ML 코드 리뷰에서 가장 흔한 결함이다. (2) 파이프라인 미사용. (3) 재현성 부재. 디스트랙터: 열 단위 처리여도 테스트 세트의 통계를 썼다는 사실이 누수다. 0.2 는 일반적인 비율이다. score 는 추정기 종류에 맞는 지표(회귀는 R²)를 반환한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"df[\"target_mean_by_city\"] = df.groupby(\"city\")[\"target\"].transform(\"mean\")\nXtr, Xte = split(df, 0.8)\nmodel.fit(Xtr.drop(\"target\", axis=1), Xtr[\"target\"])","items":[{"txt":"타깃 인코딩을 전체 데이터로 계산했다. 각 행의 특성에 자기 자신의 타깃 값이 섞여 들어가 심각한 누수가 된다.","bad":true},{"txt":"분할 전에 특성을 만들었으므로 테스트 세트의 타깃 정보가 학습 특성에 포함된다.","bad":true},{"txt":"타깃 인코딩에 스무딩이나 폴드 내 계산이 없어, 표본이 적은 도시에서 과적합이 심해진다.","bad":true},{"txt":"groupby transform 은 원본 순서를 유지하므로 인덱스 정렬 문제만 주의하면 누수는 없다.","bad":false},{"txt":"범주형 변수를 숫자로 바꾸면 항상 성능이 떨어지므로 원핫 인코딩만 써야 한다.","bad":false},{"txt":"drop 에 axis=1 을 지정하면 타깃이 제거되지 않아 학습이 실패한다.","bad":false}],"ex":"결함 3가지: 전부 타깃 인코딩의 누수 문제다. 교차검증 폴드 안에서 학습 폴드만으로 계산하고 스무딩을 적용해야 한다. 실무에서 '검증 성능은 좋은데 프로덕션에서 무너지는' 대표 원인이다. 디스트랙터: 순서 유지와 누수는 무관하다. 타깃 인코딩은 고카디널리티에서 유용한 정당한 기법이다. axis=1 은 열 제거로 정상 동작한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X = df.drop(\"churn\", axis=1)\ny = df[\"churn\"]\nmodel = RandomForestClassifier().fit(X, y)\nprint(\"accuracy:\", accuracy_score(y, model.predict(X)))","items":[{"txt":"학습에 쓴 데이터로 평가했다. 학습 정확도는 일반화 성능을 전혀 말해 주지 않는다.","bad":true},{"txt":"이탈 예측은 보통 불균형 문제인데 정확도만 본다. 이탈률이 3% 면 전부 '유지' 로 답해도 97% 다.","bad":true},{"txt":"df 에 고객 ID·가입일 같은 식별자나 미래 정보가 남아 있는지 확인하지 않았다. 그대로 넣으면 누수·과적합이 생긴다.","bad":true},{"txt":"RandomForest 는 과적합에 강하므로 학습 데이터 평가도 신뢰할 수 있다.","bad":false},{"txt":"drop 으로 타깃을 제거하면 원본 df 도 함께 변경되어 이후 코드가 깨진다.","bad":false},{"txt":"accuracy_score 의 인자 순서가 (예측, 정답) 이어야 하므로 결과가 뒤집힌다.","bad":false}],"ex":"결함 3가지: (1) 학습 데이터로 평가. (2) 불균형에 정확도 사용. (3) 특성 점검 부재. 디스트랙터: RandomForest 도 학습 데이터에서는 거의 100% 를 낸다. drop 은 기본적으로 복사를 반환한다. accuracy_score 는 인자 순서에 대칭이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"for lr in [0.01, 0.1, 0.3]:\n    for depth in [3, 5, 7]:\n        m = train(lr, depth, Xtr, ytr)\n        s = m.score(Xte, yte)\n        if s &gt; best: best, params = s, (lr, depth)\nprint(\"최종 성능:\", best)","items":[{"txt":"테스트 세트로 하이퍼파라미터를 골랐다. 그 세트는 더 이상 미본 데이터가 아니므로 best 는 낙관적으로 편향된다.","bad":true},{"txt":"검증 세트가 따로 없다. 튜닝은 검증으로 하고 테스트는 마지막에 한 번만 써야 한다.","bad":true},{"txt":"단일 분할로 비교해 분할 운에 따라 최적 조합이 바뀐다. 교차검증이 필요하다.","bad":true},{"txt":"그리드가 9개뿐이라 탐색이 부족한 것이 핵심 결함이며 베이지안 최적화가 필수다.","bad":false},{"txt":"학습률과 깊이를 함께 탐색하면 상호작용 때문에 결과가 무의미해진다.","bad":false},{"txt":"best 초기값을 지정하지 않으면 첫 비교에서 항상 실패한다.","bad":false}],"ex":"결함 3가지: (1) 테스트 세트 오염. (2) 검증 세트 부재. (3) 단일 분할 비교. 디스트랙터: 탐색 예산은 자원에 따른 선택이다. 상호작용이 있으니 함께 탐색하는 것이 맞다. 초기값은 코드 스니펫 밖에 있을 수 있어 결함으로 세지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"df = df.fillna(df.mean())\nXtr, Xte = split(df, 0.8)","items":[{"txt":"결측값을 전체 평균으로 채운 뒤 분할했다. 테스트 세트의 값이 학습 데이터의 대체값에 반영되는 누수다.","bad":true},{"txt":"결측 자체가 신호일 수 있는데 그 정보를 버린다. 결측 여부 표시 열을 함께 만드는 편이 낫다.","bad":true},{"txt":"df.mean() 은 수치형만 계산하므로 범주형 결측은 그대로 남는다. 조용히 처리되지 않는다.","bad":true},{"txt":"fillna 는 원본을 변경하므로 df 를 복사해야 하는 것이 핵심 결함이다.","bad":false},{"txt":"평균 대체는 항상 중앙값보다 나쁘므로 median 을 써야 한다.","bad":false},{"txt":"결측이 있는 행은 모두 제거하는 것이 유일하게 통계적으로 올바른 처리다.","bad":false}],"ex":"결함 3가지: (1) 분할 전 대체. (2) 결측 정보 손실. (3) 범주형 미처리. 디스트랙터: fillna 는 기본적으로 새 객체를 반환한다. 평균과 중앙값의 우열은 분포에 따라 다르다. 행 제거는 표본을 잃고 편향을 만들 수 있어 '유일하게 올바른' 처리가 아니다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"smote = SMOTE()\nX_res, y_res = smote.fit_resample(X, y)\nXtr, Xte, ytr, yte = train_test_split(X_res, y_res, test_size=0.2)","items":[{"txt":"오버샘플링을 분할 전에 적용했다. 합성된 샘플이 학습·테스트에 나뉘어 들어가 사실상 같은 데이터를 평가하게 된다.","bad":true},{"txt":"테스트 세트의 클래스 분포가 인위적으로 균형이 되어, 실제 운영 환경의 성능을 반영하지 못한다.","bad":true},{"txt":"리샘플링을 파이프라인에 넣지 않아 교차검증에서도 같은 누수가 반복된다.","bad":true},{"txt":"SMOTE 는 소수 클래스만 늘리므로 테스트 세트에 영향을 주지 않는다.","bad":false},{"txt":"오버샘플링보다 언더샘플링이 항상 우월하므로 방법 선택이 결함이다.","bad":false},{"txt":"fit_resample 은 원본 인덱스를 유지하므로 분할 시 중복이 발생하지 않는다.","bad":false}],"ex":"결함 3가지: 전부 리샘플링 시점 문제다. 분할 후 학습 세트에만 적용하고, 테스트는 원래 분포를 유지해야 한다. 디스트랙터: 소수 클래스만 늘려도 그 합성 샘플이 양쪽에 흩어진다. 언더샘플링은 정보를 버려 항상 우월하지 않다. 합성 샘플은 원본 인덱스를 갖지 않는다."}],"th":{"sum":"ML 코드 리뷰는 대개 **누수(leakage) 사냥**이다: 학습이 알아서는 안 되는 정보를 어디서 얻었는가.","body":[{"h":"누수는 순서에서 온다","t":"스케일링·결측 대체·차원 축소·특성 선택·리샘플링·타깃 인코딩 — 이 중 하나라도 분할 전에 하면 테스트 정보가 학습에 흘러든다. 규칙은 하나다: fit 은 학습 폴드에서만, transform 은 양쪽에. Pipeline 으로 묶어 교차검증에 넣으면 구조적으로 막힌다. 조기 종료를 테스트 세트로 하는 것, 테스트로 하이퍼파라미터를 고르는 것도 같은 누수다."},{"h":"미래와 그룹","t":"예측 시점에 존재하지 않는 특성(다음 날 매출, 사후 집계)은 검증에서만 빛난다. 특성마다 '가용 시점' 을 확인한다. 같은 사용자·같은 세션의 행이 학습과 검증에 나뉘면 그것도 누수이므로 GroupKFold·TimeSeriesSplit 을 쓴다. 중복 행 역시 양쪽에 흩어질 수 있다."},{"h":"지표가 목표를 반영하는가","t":"불균형 데이터의 정확도는 아무것도 말해 주지 않는다. 클래스 가중치를 주면서 정확도로 평가하면 학습 목표와 평가가 어긋난다. 임계값 0.5 는 기본값일 뿐이고, 보정되지 않은 확률의 0.5 는 확률적 의미가 없다. 기준선과 비교하지 않은 수치는 좋은지 나쁜지 알 수 없다."},{"h":"학습-서빙 왜곡","t":"모델만 저장하고 전처리기를 빼면 서빙에서 다른 특성을 만든다. get_dummies 를 서빙에서 다시 호출하면 열 구성이 달라진다. 열 순서·미본 범주·라이브러리 버전은 모두 조용히 틀린 예측을 낸다. 저장 대상은 모델이 아니라 파이프라인 전체다."}],"code":{"c":"# 결함: 분할 전 스케일링 + 테스트로 튜닝 + 정확도만 봄\nXs = StandardScaler().fit_transform(X)          # 전체로 fit → 누수\nXtr, Xte, ytr, yte = train_test_split(Xs, y)\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    if m.score(Xte, yte) > best: best, bd = m.score(Xte, yte), d\nprint(best)                                      # 낙관적 수치\n\n# 고침: 파이프라인 + 검증/테스트 분리 + 지표 정의\nXtr, Xte, ytr, yte = train_test_split(X, y, stratify=y, random_state=42)\npipe = Pipeline([(\"sc\", StandardScaler()), (\"clf\", GradientBoostingClassifier())])\ngs = GridSearchCV(pipe, {\"clf__max_depth\":[3,5,7]},\n                  cv=StratifiedKFold(5, shuffle=True, random_state=42),\n                  scoring=\"average_precision\")   # 불균형이면 PR-AUC\ngs.fit(Xtr, ytr)                                 # 폴드 안에서만 fit → 누수 없음\nprint(gs.best_score_)                            # 튜닝 성능\nprint(average_precision_score(yte, gs.predict_proba(Xte)[:,1]))  # 테스트는 마지막 한 번","cap":"Pipeline + GridSearchCV 는 누수를 구조적으로 막는다"},"key":["fit 은 학습 폴드에서만. 스케일링·대체·PCA·특성선택·리샘플링 전부 해당","Pipeline 으로 묶어 교차검증에 넣으면 누수가 구조적으로 막힌다","테스트 세트로 튜닝·조기 종료를 하지 않는다. train/valid/test 세 갈래","특성마다 '예측 시점에 있는 값인가' 를 확인한다. 그룹·시간 구조면 전용 분할","불균형에 정확도 금지. 학습 목표와 평가 지표를 일치시키고 기준선과 비교한다","저장하는 것은 모델이 아니라 파이프라인 전체 + 버전 + 데이터 버전"]}},{"t":"코드 리뷰 II","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X = df[[\"temp\", \"humidity\", \"sales_next_day\"]]\ny = df[\"sales_today\"]\nmodel.fit(X, y)","items":[{"txt":"다음 날 매출을 특성으로 써서 오늘 매출을 예측한다. 예측 시점에 존재하지 않는 정보라 프로덕션에서는 쓸 수 없다(미래 정보 누수).","bad":true},{"txt":"검증 성능은 매우 높게 나오지만 실제 배포하면 성능이 무너진다. 특성마다 '예측 시점에 확보 가능한가' 를 확인해야 한다.","bad":true},{"txt":"변수 이름에 next_day 가 있어도 값이 과거 데이터라면 문제없다.","bad":false},{"txt":"특성이 3개뿐이라 모델이 학습할 정보가 부족한 것이 핵심 결함이다.","bad":false},{"txt":"temp 와 humidity 는 상관이 높아 다중공선성 때문에 학습이 실패한다.","bad":false},{"txt":"시계열 데이터에는 회귀 모델을 쓸 수 없으므로 모델 선택 자체가 잘못이다.","bad":false}],"ex":"결함 2가지: 같은 뿌리인 미래 정보 누수다. 각 특성의 '가용 시점' 을 명시적으로 문서화하고, 시간 기준 분할로 검증하면 드러난다. 디스트랙터: 이름과 무관하게 시점이 문제이고 여기서는 명확히 미래 값이다. 특성 수는 문제 정의에 따른다. 다중공선성은 계수 해석을 어렵게 하지만 학습을 실패시키지 않는다. 회귀 모델은 시계열에도 널리 쓰인다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"kf = KFold(n_splits=5, shuffle=True)\nscores = cross_val_score(model, X, y, cv=kf)\nprint(scores.mean())","items":[{"txt":"시계열이나 그룹 구조가 있는 데이터라면 무작위 셔플이 누수를 만든다. 같은 사용자·같은 시점의 데이터가 학습과 검증에 나뉘어 들어간다.","bad":true},{"txt":"shuffle=True 인데 random_state 가 없어 실행마다 결과가 달라진다.","bad":true},{"txt":"클래스 불균형이 있으면 폴드마다 분포가 달라진다. StratifiedKFold 가 필요하다.","bad":true},{"txt":"KFold 는 항상 셔플하므로 shuffle 인자는 무시된다.","bad":false},{"txt":"cross_val_score 는 파이프라인을 받을 수 없어 전처리를 미리 해야 한다.","bad":false},{"txt":"폴드 수 5는 너무 적어 편향이 크므로 최소 20 이어야 한다.","bad":false}],"ex":"결함 3가지: (1) 그룹·시간 구조 무시 — GroupKFold·TimeSeriesSplit 이 필요하다. (2) 재현성 부재. (3) 계층화 부재. 디스트랙터: KFold 의 기본은 shuffle=False 다. cross_val_score 는 파이프라인을 받으며, 그게 누수를 막는 정석이다. 폴드 수는 표본 크기와 비용의 절충이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"model = LogisticRegression()\nmodel.fit(Xtr, ytr)\nimportance = model.coef_[0]\nprint(\"가장 중요한 특성:\", X.columns[importance.argmax()])","items":[{"txt":"특성을 표준화하지 않았다면 계수 크기를 그대로 비교할 수 없다. 단위가 큰 특성의 계수는 작게 나온다.","bad":true},{"txt":"argmax 는 가장 큰 양수 계수만 고른다. 음의 방향으로 강한 특성은 완전히 무시된다. 절댓값을 써야 한다.","bad":true},{"txt":"계수는 상관이 아니라 조건부 기여이고, 다중공선성이 있으면 크기와 부호가 불안정해진다. 중요도 해석에 주의가 필요하다.","bad":true},{"txt":"LogisticRegression 은 coef_ 를 제공하지 않으므로 이 코드는 실행되지 않는다.","bad":false},{"txt":"규제(regularization)를 끄지 않으면 계수가 0 이 되어 비교가 불가능하다.","bad":false},{"txt":"특성 중요도는 트리 모델에서만 정의되므로 선형 모델에서는 의미가 없다.","bad":false}],"ex":"결함 3가지: (1) 스케일 미고려. (2) 절댓값 미사용. (3) 계수 해석의 한계. 디스트랙터: coef_ 는 존재한다. 기본 L2 규제는 계수를 줄이지만 0 으로 만들지 않는다(L1 이 희소화한다). 선형 모델의 계수도 정당한 해석 수단이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"best_model = None\nfor seed in range(50):\n    m = train(Xtr, ytr, seed=seed)\n    if m.score(Xval, yval) &gt; best_score:\n        best_model, best_score = m, m.score(Xval, yval)\nreport(best_score)","items":[{"txt":"시드를 50번 바꿔 검증 성능이 가장 좋은 것을 고르고 그 값을 보고했다. 검증 세트에 과적합된 낙관적 수치다.","bad":true},{"txt":"선택은 검증으로 하되 보고는 별도 테스트 세트로 해야 한다.","bad":true},{"txt":"시드 선택은 성능 개선이 아니라 분산이다. 여러 시드의 평균과 표준편차를 함께 보고하는 편이 정직하다.","bad":true},{"txt":"시드를 고정하지 않으면 재현이 불가능하므로 50번 탐색이 유일한 해법이다.","bad":false},{"txt":"검증 세트를 여러 번 쓰면 데이터가 소모되어 크기가 줄어든다.","bad":false},{"txt":"m.score 를 두 번 호출하면 모델 상태가 변해 값이 달라진다.","bad":false}],"ex":"결함 3가지: (1) 검증 세트 과적합. (2) 보고 세트 분리 부재. (3) 분산을 성능으로 착각. 디스트랙터: 재현성은 시드 고정으로 얻고 최선 탐색과 다르다. 세트를 재사용해도 크기는 줄지 않는다(정보가 소모될 뿐이다). score 는 상태를 바꾸지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"pickle.dump(model, open(\"model.pkl\", \"wb\"))\n# 배포 서버\nmodel = pickle.load(open(\"model.pkl\", \"rb\"))\npred = model.predict(new_data)","items":[{"txt":"라이브러리 버전을 함께 고정하지 않았다. 학습·서빙의 scikit-learn 버전이 다르면 로드가 실패하거나 조용히 다른 결과를 낸다.","bad":true},{"txt":"전처리기를 함께 저장하지 않았다. 모델만 옮기면 서빙 쪽 전처리가 학습과 달라진다(학습-서빙 왜곡).","bad":true},{"txt":"pickle 은 임의 코드 실행이 가능한 형식이다. 신뢰 경계를 넘어 전달되면 위험하다.","bad":true},{"txt":"pickle 은 버전 정보를 파일에 담으므로 호환성 문제가 자동으로 감지된다.","bad":false},{"txt":"open 을 with 문으로 감싸지 않아 파일 핸들이 누수되는 것이 핵심 결함이다.","bad":false},{"txt":"predict 는 학습 시와 같은 열 순서를 자동으로 맞춰 주므로 전처리 저장은 불필요하다.","bad":false}],"ex":"결함 3가지: (1) 버전 미고정. (2) 전처리기 미포함 — 파이프라인 전체를 저장한다. (3) pickle 의 보안 위험. 디스트랙터: pickle 은 경고를 낼 수는 있지만 자동 감지·차단하지 않는다. 파일 핸들은 부차적이다. predict 는 열 이름을 맞춰 주지 않는다(numpy 배열이면 순서만 본다)."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"df = pd.read_csv(\"train.csv\")\ndf = df.drop_duplicates()\nX, y = df.drop(\"y\", axis=1), df[\"y\"]\nmodel.fit(X, y)","items":[{"txt":"중복 제거를 전체에 적용한 뒤 분할하지 않았다. 원본에 완전 중복 행이 있었다면 학습과 검증에 같은 행이 들어갈 수 있다.","bad":true},{"txt":"범주형 열을 인코딩하지 않았다. 문자열이 섞여 있으면 학습이 실패하거나 조용히 잘못 처리된다.","bad":true},{"txt":"특성에 ID 나 인덱스 열이 남아 있는지 확인하지 않았다. 남으면 모델이 그것으로 외운다.","bad":true},{"txt":"drop_duplicates 는 인덱스를 재설정하지 않아 이후 병합에서 오류가 나는 것이 핵심이다.","bad":false},{"txt":"read_csv 는 dtype 을 추론하므로 어떤 열도 잘못 해석되지 않는다.","bad":false},{"txt":"중복 행은 오히려 가중치 역할을 하므로 제거하면 성능이 떨어진다.","bad":false}],"ex":"결함 3가지: (1) 중복과 분할의 관계 미고려. (2) 범주형 미인코딩. (3) 식별자 열 점검 부재. 디스트랙터: 인덱스 재설정은 사소하다. read_csv 의 추론은 자주 틀린다(전화번호가 숫자가 되는 식). 중복은 누수와 편향을 만들 수 있어 제거가 일반적이다."}],"th":{"sum":"ML 코드 리뷰는 대개 **누수(leakage) 사냥**이다: 학습이 알아서는 안 되는 정보를 어디서 얻었는가.","body":[{"h":"누수는 순서에서 온다","t":"스케일링·결측 대체·차원 축소·특성 선택·리샘플링·타깃 인코딩 — 이 중 하나라도 분할 전에 하면 테스트 정보가 학습에 흘러든다. 규칙은 하나다: fit 은 학습 폴드에서만, transform 은 양쪽에. Pipeline 으로 묶어 교차검증에 넣으면 구조적으로 막힌다. 조기 종료를 테스트 세트로 하는 것, 테스트로 하이퍼파라미터를 고르는 것도 같은 누수다."},{"h":"미래와 그룹","t":"예측 시점에 존재하지 않는 특성(다음 날 매출, 사후 집계)은 검증에서만 빛난다. 특성마다 '가용 시점' 을 확인한다. 같은 사용자·같은 세션의 행이 학습과 검증에 나뉘면 그것도 누수이므로 GroupKFold·TimeSeriesSplit 을 쓴다. 중복 행 역시 양쪽에 흩어질 수 있다."},{"h":"지표가 목표를 반영하는가","t":"불균형 데이터의 정확도는 아무것도 말해 주지 않는다. 클래스 가중치를 주면서 정확도로 평가하면 학습 목표와 평가가 어긋난다. 임계값 0.5 는 기본값일 뿐이고, 보정되지 않은 확률의 0.5 는 확률적 의미가 없다. 기준선과 비교하지 않은 수치는 좋은지 나쁜지 알 수 없다."},{"h":"학습-서빙 왜곡","t":"모델만 저장하고 전처리기를 빼면 서빙에서 다른 특성을 만든다. get_dummies 를 서빙에서 다시 호출하면 열 구성이 달라진다. 열 순서·미본 범주·라이브러리 버전은 모두 조용히 틀린 예측을 낸다. 저장 대상은 모델이 아니라 파이프라인 전체다."}],"code":{"c":"# 결함: 분할 전 스케일링 + 테스트로 튜닝 + 정확도만 봄\nXs = StandardScaler().fit_transform(X)          # 전체로 fit → 누수\nXtr, Xte, ytr, yte = train_test_split(Xs, y)\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    if m.score(Xte, yte) > best: best, bd = m.score(Xte, yte), d\nprint(best)                                      # 낙관적 수치\n\n# 고침: 파이프라인 + 검증/테스트 분리 + 지표 정의\nXtr, Xte, ytr, yte = train_test_split(X, y, stratify=y, random_state=42)\npipe = Pipeline([(\"sc\", StandardScaler()), (\"clf\", GradientBoostingClassifier())])\ngs = GridSearchCV(pipe, {\"clf__max_depth\":[3,5,7]},\n                  cv=StratifiedKFold(5, shuffle=True, random_state=42),\n                  scoring=\"average_precision\")   # 불균형이면 PR-AUC\ngs.fit(Xtr, ytr)                                 # 폴드 안에서만 fit → 누수 없음\nprint(gs.best_score_)                            # 튜닝 성능\nprint(average_precision_score(yte, gs.predict_proba(Xte)[:,1]))  # 테스트는 마지막 한 번","cap":"Pipeline + GridSearchCV 는 누수를 구조적으로 막는다"},"key":["fit 은 학습 폴드에서만. 스케일링·대체·PCA·특성선택·리샘플링 전부 해당","Pipeline 으로 묶어 교차검증에 넣으면 누수가 구조적으로 막힌다","테스트 세트로 튜닝·조기 종료를 하지 않는다. train/valid/test 세 갈래","특성마다 '예측 시점에 있는 값인가' 를 확인한다. 그룹·시간 구조면 전용 분할","불균형에 정확도 금지. 학습 목표와 평가 지표를 일치시키고 기준선과 비교한다","저장하는 것은 모델이 아니라 파이프라인 전체 + 버전 + 데이터 버전"]}},{"t":"코드 리뷰 III","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"class Model:\n    def fit(self, X, y):\n        self.mean_ = X.mean()\n        return self\n    def transform(self, X):\n        return X - X.mean()","items":[{"txt":"transform 이 fit 에서 학습한 self.mean_ 을 쓰지 않고 입력 X 의 평균을 다시 계산한다. 테스트 데이터에 그 자신의 통계를 적용하는 누수이자 버그다.","bad":true},{"txt":"fit 하지 않고 transform 을 호출해도 예외가 나지 않는다. 학습 여부를 확인해야 한다.","bad":true},{"txt":"scikit-learn 규약상 transform 은 fit 의 상태를 쓰면 안 되므로 이 구현이 옳다.","bad":false},{"txt":"fit 이 self 를 반환하지 않으면 파이프라인에서 쓸 수 없는 것이 핵심 결함이다.","bad":false},{"txt":"mean_ 처럼 밑줄로 끝나는 이름은 비공개 속성이라 외부에서 접근할 수 없다.","bad":false},{"txt":"X.mean() 은 열 단위 평균이 아니라 전체 평균을 반환하므로 결과가 스칼라가 된다.","bad":false}],"ex":"결함 2가지: (1) 학습된 상태를 쓰지 않음 — 이 한 줄 차이가 조용한 누수를 만든다. (2) 미학습 검사 부재. 디스트랙터: 규약은 정확히 반대로, transform 은 fit 의 상태를 써야 한다. fit 은 self 를 반환하고 있다. 밑줄 접미사는 '학습된 속성' 이라는 관례 표기다. DataFrame 의 mean() 은 열별 평균을 준다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"train = df[df.date &lt; \"2026-01-01\"]\ntest  = df[df.date &gt;= \"2026-01-01\"]\nfeat = make_features(df)          # 전체로 특성 생성","items":[{"txt":"시간 기준으로 분할한 뒤 특성을 전체 데이터로 만들었다. 이동평균·누적합 같은 특성이라면 미래 정보가 학습 구간에 들어간다.","bad":true},{"txt":"특성 생성 결과를 분할된 train/test 와 다시 맞추는 과정이 없다. 인덱스가 어긋나면 조용히 잘못된 쌍이 만들어진다.","bad":true},{"txt":"시계열 검증이 단일 분할이라 시점 변화에 따른 성능 변동을 볼 수 없다. 롤링 윈도 검증이 필요하다.","bad":true},{"txt":"날짜를 문자열로 비교하면 항상 실패하므로 datetime 변환이 필수다.","bad":false},{"txt":"시계열 데이터는 무작위 분할이 더 정확한 평가를 주므로 시간 분할이 잘못이다.","bad":false},{"txt":"make_features 를 한 번만 호출하면 계산이 절약되므로 전체 적용이 권장된다.","bad":false}],"ex":"결함 3가지: (1) 전체 데이터 특성 생성. (2) 정렬 위험. (3) 단일 시점 검증. 디스트랙터: ISO 형식 문자열 비교는 사전순으로 올바르게 동작한다. 시계열에 무작위 분할은 대표적인 누수다. 계산 절약보다 누수 방지가 우선이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"y_pred = model.predict(Xte)\nprint(classification_report(yte, y_pred))\n# 정확도 0.94 → 배포 승인","items":[{"txt":"정확도 하나로 배포를 결정했다. 불균형이면 다수 클래스만 맞혀도 높게 나온다. 클래스별 재현율·정밀도를 봐야 한다.","bad":true},{"txt":"오탐과 미탐의 비용이 다른 문제일 수 있는데 비용을 반영한 지표가 없다.","bad":true},{"txt":"기준선(항상 다수 클래스 예측, 기존 규칙 기반)과 비교하지 않았다. 0.94 가 개선인지 알 수 없다.","bad":true},{"txt":"classification_report 는 정확도만 출력하므로 다른 지표를 볼 수 없다.","bad":false},{"txt":"테스트 세트 성능이 0.9 를 넘으면 통계적으로 배포에 충분하다.","bad":false},{"txt":"배포 전에는 반드시 A/B 테스트를 해야 하므로 오프라인 지표는 무의미하다.","bad":false}],"ex":"결함 3가지: (1) 단일 지표 의존. (2) 비용 미반영. (3) 기준선 부재. 디스트랙터: classification_report 는 클래스별 지표를 함께 출력한다(즉 이미 정보가 있는데 보지 않은 것이 문제다). 절대 수치로 충분함을 판단할 수 없다. 오프라인 지표는 A/B 이전의 필수 관문이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"def predict_batch(rows):\n    df = pd.DataFrame(rows)\n    return model.predict(df)","items":[{"txt":"열 순서와 이름이 학습 시와 같은지 검증하지 않는다. dict 순서가 다르면 조용히 다른 특성으로 예측한다.","bad":true},{"txt":"학습 때 본 적 없는 범주값이 오면 처리 방식이 정의되지 않았다.","bad":true},{"txt":"입력 값의 범위·타입 검증이 없어, 학습 분포를 크게 벗어난 값에도 그대로 예측을 반환한다.","bad":true},{"txt":"DataFrame 생성 시 열 순서는 항상 알파벳순으로 정렬되므로 순서 문제가 없다.","bad":false},{"txt":"predict 는 입력이 잘못되면 반드시 예외를 던지므로 검증이 불필요하다.","bad":false},{"txt":"배치 예측은 단건보다 느리므로 루프로 바꾸는 것이 핵심 개선이다.","bad":false}],"ex":"결함 3가지: (1) 스키마 검증 부재. (2) 미본 범주 처리 부재. (3) 분포 이탈 미감지. 디스트랙터: DataFrame 은 입력 키 순서를 따른다. 열 수가 맞으면 예외 없이 잘못된 예측을 낸다 — 그게 가장 위험하다. 배치가 오히려 빠르다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"mlflow.log_metric(\"auc\", auc)\nmlflow.log_param(\"lr\", 0.01)\nmlflow.sklearn.log_model(model, \"model\")","items":[{"txt":"데이터 버전을 기록하지 않았다. 같은 코드·같은 하이퍼파라미터라도 데이터가 다르면 재현되지 않는다.","bad":true},{"txt":"난수 시드와 라이브러리 버전을 남기지 않아 실험을 재현할 수 없다.","bad":true},{"txt":"전처리 파이프라인이 아니라 모델만 저장해 서빙 시 학습과 다른 전처리를 쓰게 된다.","bad":true},{"txt":"실험 추적 도구를 쓰면 데이터·환경이 자동으로 기록되므로 별도 로깅이 불필요하다.","bad":false},{"txt":"AUC 하나만 기록하면 지표 비교가 불가능하므로 최소 10개 지표가 필요하다.","bad":false},{"txt":"log_model 은 모델을 직렬화하지 않고 참조만 저장하므로 배포에 쓸 수 없다.","bad":false}],"ex":"결함 3가지: (1) 데이터 버전 미기록. (2) 시드·환경 미기록. (3) 파이프라인 미저장. 디스트랙터: 자동 로깅은 일부만 잡고 데이터 버전은 직접 남겨야 한다. 지표 개수에 기준은 없다. log_model 은 실제로 직렬화해 저장한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"pca = PCA(n_components=50).fit(X)\nXp = pca.transform(X)\nselector = SelectKBest(k=20).fit(Xp, y)\nXtr, Xte = split(selector.transform(Xp), 0.8)","items":[{"txt":"차원 축소와 특성 선택을 전체 데이터로 학습한 뒤 분할했다. 두 단계 모두 테스트 정보를 흡수한 누수다.","bad":true},{"txt":"SelectKBest 는 타깃을 쓰므로 특히 심각하다. 테스트 세트의 타깃이 특성 선택에 영향을 준다.","bad":true},{"txt":"PCA 전에 스케일링을 하지 않았다. 분산이 큰 열이 주성분을 지배한다.","bad":true},{"txt":"PCA 는 비지도 방법이므로 전체 데이터로 학습해도 누수가 아니다.","bad":false},{"txt":"PCA 후 SelectKBest 를 적용하면 주성분이 이미 직교하므로 선택이 무의미해 실행이 실패한다.","bad":false},{"txt":"n_components=50 은 원본 차원보다 클 수 있으므로 항상 오류가 난다.","bad":false}],"ex":"결함 3가지: (1) 분할 전 학습. (2) 타깃 사용 단계의 누수. (3) PCA 전 스케일링 누락. 파이프라인으로 묶어 폴드 안에서만 fit 해야 한다. 디스트랙터: 비지도 변환도 테스트 분포를 흡수한다. 직교 주성분에도 타깃 관련성 차이가 있어 선택은 의미가 있다. n_components 가 크면 오류가 나지만 여기서는 알 수 없다."}],"th":{"sum":"ML 코드 리뷰는 대개 **누수(leakage) 사냥**이다: 학습이 알아서는 안 되는 정보를 어디서 얻었는가.","body":[{"h":"누수는 순서에서 온다","t":"스케일링·결측 대체·차원 축소·특성 선택·리샘플링·타깃 인코딩 — 이 중 하나라도 분할 전에 하면 테스트 정보가 학습에 흘러든다. 규칙은 하나다: fit 은 학습 폴드에서만, transform 은 양쪽에. Pipeline 으로 묶어 교차검증에 넣으면 구조적으로 막힌다. 조기 종료를 테스트 세트로 하는 것, 테스트로 하이퍼파라미터를 고르는 것도 같은 누수다."},{"h":"미래와 그룹","t":"예측 시점에 존재하지 않는 특성(다음 날 매출, 사후 집계)은 검증에서만 빛난다. 특성마다 '가용 시점' 을 확인한다. 같은 사용자·같은 세션의 행이 학습과 검증에 나뉘면 그것도 누수이므로 GroupKFold·TimeSeriesSplit 을 쓴다. 중복 행 역시 양쪽에 흩어질 수 있다."},{"h":"지표가 목표를 반영하는가","t":"불균형 데이터의 정확도는 아무것도 말해 주지 않는다. 클래스 가중치를 주면서 정확도로 평가하면 학습 목표와 평가가 어긋난다. 임계값 0.5 는 기본값일 뿐이고, 보정되지 않은 확률의 0.5 는 확률적 의미가 없다. 기준선과 비교하지 않은 수치는 좋은지 나쁜지 알 수 없다."},{"h":"학습-서빙 왜곡","t":"모델만 저장하고 전처리기를 빼면 서빙에서 다른 특성을 만든다. get_dummies 를 서빙에서 다시 호출하면 열 구성이 달라진다. 열 순서·미본 범주·라이브러리 버전은 모두 조용히 틀린 예측을 낸다. 저장 대상은 모델이 아니라 파이프라인 전체다."}],"code":{"c":"# 결함: 분할 전 스케일링 + 테스트로 튜닝 + 정확도만 봄\nXs = StandardScaler().fit_transform(X)          # 전체로 fit → 누수\nXtr, Xte, ytr, yte = train_test_split(Xs, y)\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    if m.score(Xte, yte) > best: best, bd = m.score(Xte, yte), d\nprint(best)                                      # 낙관적 수치\n\n# 고침: 파이프라인 + 검증/테스트 분리 + 지표 정의\nXtr, Xte, ytr, yte = train_test_split(X, y, stratify=y, random_state=42)\npipe = Pipeline([(\"sc\", StandardScaler()), (\"clf\", GradientBoostingClassifier())])\ngs = GridSearchCV(pipe, {\"clf__max_depth\":[3,5,7]},\n                  cv=StratifiedKFold(5, shuffle=True, random_state=42),\n                  scoring=\"average_precision\")   # 불균형이면 PR-AUC\ngs.fit(Xtr, ytr)                                 # 폴드 안에서만 fit → 누수 없음\nprint(gs.best_score_)                            # 튜닝 성능\nprint(average_precision_score(yte, gs.predict_proba(Xte)[:,1]))  # 테스트는 마지막 한 번","cap":"Pipeline + GridSearchCV 는 누수를 구조적으로 막는다"},"key":["fit 은 학습 폴드에서만. 스케일링·대체·PCA·특성선택·리샘플링 전부 해당","Pipeline 으로 묶어 교차검증에 넣으면 누수가 구조적으로 막힌다","테스트 세트로 튜닝·조기 종료를 하지 않는다. train/valid/test 세 갈래","특성마다 '예측 시점에 있는 값인가' 를 확인한다. 그룹·시간 구조면 전용 분할","불균형에 정확도 금지. 학습 목표와 평가 지표를 일치시키고 기준선과 비교한다","저장하는 것은 모델이 아니라 파이프라인 전체 + 버전 + 데이터 버전"]}},{"t":"코드 리뷰 IV","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X[\"age\"] = X[\"age\"].fillna(-999)\nmodel = GradientBoostingClassifier().fit(X, y)","items":[{"txt":"결측을 극단값으로 채웠다. 트리 모델은 이를 실제 값으로 학습해 나이 분포를 왜곡한다.","bad":true},{"txt":"결측 여부를 나타내는 별도 열이 없어, 모델이 '결측' 이라는 정보를 명시적으로 쓸 수 없다.","bad":true},{"txt":"서빙에서 같은 대체 규칙이 적용되는지 보장하는 장치가 없다. 학습-서빙 왜곡이 생긴다.","bad":true},{"txt":"트리 모델은 결측을 자동으로 처리하므로 어떤 대체도 필요 없다.","bad":false},{"txt":"-999 대신 0 을 쓰면 문제가 완전히 해결된다.","bad":false},{"txt":"fillna 는 원본을 변경하지 않으므로 X 에 반영되지 않아 코드가 무효다.","bad":false}],"ex":"결함 3가지: (1) 극단값 대체의 왜곡. (2) 결측 표시 열 부재. (3) 서빙 일관성 보장 부재. 디스트랙터: scikit-learn 의 GradientBoosting 은 결측을 자동 처리하지 않는다(HistGradientBoosting 은 가능). 0 은 실제 값과 겹쳐 더 나쁠 수 있다. 대입문으로 X 에 반영된다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"model.fit(Xtr, ytr, eval_set=[(Xte, yte)], early_stopping_rounds=50)\nprint(\"테스트 AUC:\", auc(yte, model.predict_proba(Xte)[:,1]))","items":[{"txt":"조기 종료를 테스트 세트로 수행했다. 테스트가 학습 과정에 개입했으므로 보고된 AUC 는 낙관적이다.","bad":true},{"txt":"조기 종료용 검증 세트를 따로 두지 않았다. train/valid/test 세 갈래가 필요하다.","bad":true},{"txt":"early_stopping_rounds 를 쓰면 과적합이 원리적으로 방지되므로 테스트 세트를 써도 무해하다.","bad":false},{"txt":"eval_set 에는 학습 세트를 넣어야 하므로 인자 자체가 잘못됐다.","bad":false},{"txt":"predict_proba 의 [:,1] 은 다중 클래스에서만 유효하므로 이진 분류에서는 오류다.","bad":false},{"txt":"AUC 는 임계값과 무관하므로 불균형 데이터에서 항상 신뢰할 수 있다.","bad":false}],"ex":"결함 2가지: (1) 테스트 세트로 조기 종료 — 흔하고 발견하기 어려운 누수다. (2) 검증 세트 분리 부재. 디스트랙터: 조기 종료는 과적합을 줄이지만 그 기준 세트는 오염된다. eval_set 에는 검증 세트를 넣는다. [:,1] 은 이진 분류의 표준 사용법이다. AUC 도 심한 불균형에서는 낙관적으로 보일 수 있어 PR-AUC 를 함께 본다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"for col in df.columns:\n    if df[col].dtype == \"object\":\n        df[col] = LabelEncoder().fit_transform(df[col])","items":[{"txt":"범주형에 라벨 인코딩을 적용해 임의의 순서를 부여했다. 선형 모델·거리 기반 모델에서는 '서울=1, 부산=2' 같은 크기 관계를 학습한다.","bad":true},{"txt":"각 열마다 새 인코더를 만들고 저장하지 않아, 서빙에서 같은 매핑을 재현할 수 없다.","bad":true},{"txt":"학습 때 없던 값이 서빙에 오면 처리 방법이 없다. transform 이 예외를 던진다.","bad":true},{"txt":"LabelEncoder 는 원래 타깃 인코딩용이므로 특성에 쓰면 항상 예외가 발생한다.","bad":false},{"txt":"dtype 이 object 인 열은 모두 범주형이므로 판별 방식은 안전하다.","bad":false},{"txt":"트리 모델에서도 라벨 인코딩은 사용할 수 없으므로 원핫만 유효하다.","bad":false}],"ex":"결함 3가지: (1) 순서 부여의 왜곡. (2) 인코더 미저장. (3) 미본 값 처리 부재. OrdinalEncoder·OneHotEncoder 를 파이프라인에 넣고 handle_unknown 을 지정한다. 디스트랙터: LabelEncoder 는 특성에도 동작한다(권장되지 않을 뿐). object 열에는 자유 텍스트나 날짜 문자열도 섞인다. 트리 모델은 라벨 인코딩으로도 잘 동작한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"scores = []\nfor i in range(100):\n    Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.2)\n    scores.append(train_and_score(Xtr, ytr, Xte, yte))\nprint(\"성능:\", max(scores))","items":[{"txt":"100번 반복 중 최댓값을 보고했다. 분할 운이 가장 좋았던 경우이므로 기대 성능이 아니다. 평균과 분산을 보고해야 한다.","bad":true},{"txt":"반복마다 시드가 다르고 기록되지 않아 어떤 분할이었는지 재현할 수 없다.","bad":true},{"txt":"반복 100회는 과도하므로 계산 낭비가 핵심 문제다.","bad":false},{"txt":"train_test_split 은 매번 같은 분할을 반환하므로 반복이 무의미하다.","bad":false},{"txt":"test_size 를 0.2 로 고정하면 표본 크기가 달라지지 않아 분산 추정이 불가능하다.","bad":false},{"txt":"max 대신 min 을 쓰면 보수적 추정이 되어 통계적으로 올바르다.","bad":false}],"ex":"결함 2가지: (1) 최댓값 보고 — 체리피킹이다. (2) 재현성 부재. 디스트랙터: 반복 자체는 분산 추정에 유용하다. 시드 없는 split 은 매번 다른 분할을 준다. 고정 비율에서도 분할이 달라 분산을 추정할 수 있다. min 도 왜곡된 추정이며 평균±표준편차가 정직하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"if new_data_drift &gt; 0.3:\n    model = retrain(all_data)\n    deploy(model)","items":[{"txt":"드리프트 감지 시 자동으로 재학습해 즉시 배포한다. 성능 검증 단계가 없어 더 나쁜 모델이 배포될 수 있다.","bad":true},{"txt":"드리프트의 원인을 확인하지 않는다. 데이터 파이프라인 버그로 인한 이상도 드리프트로 보이며, 그 데이터로 학습하면 모델이 오염된다.","bad":true},{"txt":"롤백 경로와 이전 모델 보관이 없다.","bad":true},{"txt":"드리프트 임계값 0.3 은 통계적 근거가 있는 표준값이므로 문제없다.","bad":false},{"txt":"자동 재학습은 항상 수동보다 안전하므로 검증 단계가 불필요하다.","bad":false},{"txt":"all_data 로 학습하면 과거 데이터가 섞여 성능이 떨어지므로 최신 데이터만 써야 한다.","bad":false}],"ex":"결함 3가지: (1) 검증 없는 자동 배포 — 챌린저 모델로 비교 후 승격해야 한다. (2) 드리프트 원인 미확인. (3) 롤백 부재. 디스트랙터: 임계값은 지표·도메인마다 달라 표준값이 없다. 자동화는 검증이 있어야 안전하다. 과거 데이터 포함 여부는 문제에 따라 다르다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"model = train(X, y)\nsave(model)\n# 6개월 후\npred = model.predict(new_X)","items":[{"txt":"모델 성능 모니터링이 없다. 6개월 동안 데이터 분포가 바뀌었는데 성능 저하를 감지할 방법이 없다.","bad":true},{"txt":"입력 특성의 분포 변화(드리프트) 감시가 없다. 파이프라인 변경으로 특성 의미가 달라져도 조용히 예측을 낸다.","bad":true},{"txt":"모델 버전과 학습 시점을 예측 결과에 남기지 않아 사후 분석이 불가능하다.","bad":true},{"txt":"모델은 학습 후 변하지 않으므로 시간 경과는 성능에 영향을 주지 않는다.","bad":false},{"txt":"6개월은 짧은 기간이므로 재학습 주기로는 충분하다.","bad":false},{"txt":"predict 는 입력 분포를 자동으로 검사해 경고를 출력한다.","bad":false}],"ex":"결함 3가지: (1) 성능 모니터링 부재. (2) 드리프트 감시 부재. (3) 추적성 부재. 디스트랙터: 모델은 고정이지만 세상이 변한다. 적절한 주기는 도메인에 따르며 감시 없이는 판단할 수 없다. predict 는 분포를 검사하지 않는다."}],"th":{"sum":"ML 코드 리뷰는 대개 **누수(leakage) 사냥**이다: 학습이 알아서는 안 되는 정보를 어디서 얻었는가.","body":[{"h":"누수는 순서에서 온다","t":"스케일링·결측 대체·차원 축소·특성 선택·리샘플링·타깃 인코딩 — 이 중 하나라도 분할 전에 하면 테스트 정보가 학습에 흘러든다. 규칙은 하나다: fit 은 학습 폴드에서만, transform 은 양쪽에. Pipeline 으로 묶어 교차검증에 넣으면 구조적으로 막힌다. 조기 종료를 테스트 세트로 하는 것, 테스트로 하이퍼파라미터를 고르는 것도 같은 누수다."},{"h":"미래와 그룹","t":"예측 시점에 존재하지 않는 특성(다음 날 매출, 사후 집계)은 검증에서만 빛난다. 특성마다 '가용 시점' 을 확인한다. 같은 사용자·같은 세션의 행이 학습과 검증에 나뉘면 그것도 누수이므로 GroupKFold·TimeSeriesSplit 을 쓴다. 중복 행 역시 양쪽에 흩어질 수 있다."},{"h":"지표가 목표를 반영하는가","t":"불균형 데이터의 정확도는 아무것도 말해 주지 않는다. 클래스 가중치를 주면서 정확도로 평가하면 학습 목표와 평가가 어긋난다. 임계값 0.5 는 기본값일 뿐이고, 보정되지 않은 확률의 0.5 는 확률적 의미가 없다. 기준선과 비교하지 않은 수치는 좋은지 나쁜지 알 수 없다."},{"h":"학습-서빙 왜곡","t":"모델만 저장하고 전처리기를 빼면 서빙에서 다른 특성을 만든다. get_dummies 를 서빙에서 다시 호출하면 열 구성이 달라진다. 열 순서·미본 범주·라이브러리 버전은 모두 조용히 틀린 예측을 낸다. 저장 대상은 모델이 아니라 파이프라인 전체다."}],"code":{"c":"# 결함: 분할 전 스케일링 + 테스트로 튜닝 + 정확도만 봄\nXs = StandardScaler().fit_transform(X)          # 전체로 fit → 누수\nXtr, Xte, ytr, yte = train_test_split(Xs, y)\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    if m.score(Xte, yte) > best: best, bd = m.score(Xte, yte), d\nprint(best)                                      # 낙관적 수치\n\n# 고침: 파이프라인 + 검증/테스트 분리 + 지표 정의\nXtr, Xte, ytr, yte = train_test_split(X, y, stratify=y, random_state=42)\npipe = Pipeline([(\"sc\", StandardScaler()), (\"clf\", GradientBoostingClassifier())])\ngs = GridSearchCV(pipe, {\"clf__max_depth\":[3,5,7]},\n                  cv=StratifiedKFold(5, shuffle=True, random_state=42),\n                  scoring=\"average_precision\")   # 불균형이면 PR-AUC\ngs.fit(Xtr, ytr)                                 # 폴드 안에서만 fit → 누수 없음\nprint(gs.best_score_)                            # 튜닝 성능\nprint(average_precision_score(yte, gs.predict_proba(Xte)[:,1]))  # 테스트는 마지막 한 번","cap":"Pipeline + GridSearchCV 는 누수를 구조적으로 막는다"},"key":["fit 은 학습 폴드에서만. 스케일링·대체·PCA·특성선택·리샘플링 전부 해당","Pipeline 으로 묶어 교차검증에 넣으면 누수가 구조적으로 막힌다","테스트 세트로 튜닝·조기 종료를 하지 않는다. train/valid/test 세 갈래","특성마다 '예측 시점에 있는 값인가' 를 확인한다. 그룹·시간 구조면 전용 분할","불균형에 정확도 금지. 학습 목표와 평가 지표를 일치시키고 기준선과 비교한다","저장하는 것은 모델이 아니라 파이프라인 전체 + 버전 + 데이터 버전"]}},{"t":"코드 리뷰 V","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X = pd.get_dummies(df)\nXtr, Xte = split(X, 0.8)\nmodel.fit(Xtr, ytr)\n# 서빙\npred = model.predict(pd.get_dummies(new_df))","items":[{"txt":"서빙에서 get_dummies 를 다시 호출한다. 새 데이터의 범주 구성이 다르면 열 개수와 순서가 달라져 예측이 깨지거나 조용히 틀린다.","bad":true},{"txt":"학습 시 열 목록을 저장하지 않아 서빙에서 정렬·보완할 기준이 없다.","bad":true},{"txt":"전체 데이터로 더미 변환한 뒤 분할해, 테스트에만 있는 범주가 학습 특성 목록에 포함된다.","bad":true},{"txt":"get_dummies 는 열을 알파벳순으로 정렬하므로 순서 문제가 발생하지 않는다.","bad":false},{"txt":"predict 는 열 이름을 확인해 자동으로 맞춰 주므로 안전하다.","bad":false},{"txt":"원핫 인코딩은 차원을 늘려 성능을 떨어뜨리므로 사용 자체가 결함이다.","bad":false}],"ex":"결함 3가지: (1) 서빙에서의 재변환. (2) 열 목록 미저장. (3) 분할 전 변환. OneHotEncoder 를 파이프라인에 넣고 handle_unknown='ignore' 로 두면 전부 해결된다. 디스트랙터: 정렬돼도 존재하는 범주가 다르면 열이 달라진다. predict 는 열 이름을 맞춰 주지 않는다. 원핫은 표준 기법이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"w = compute_sample_weight(\"balanced\", ytr)\nmodel.fit(Xtr, ytr, sample_weight=w)\nprint(accuracy_score(yte, model.predict(Xte)))","items":[{"txt":"클래스 가중치로 불균형을 보정했는데 평가는 정확도로 한다. 가중 학습은 정확도를 낮추는 방향으로 작동하므로 지표가 어긋난다.","bad":true},{"txt":"가중치를 테스트 평가에는 반영하지 않으면서 학습만 바꿨다. 목표 지표를 먼저 정의해야 한다.","bad":true},{"txt":"임계값을 조정하지 않았다. 가중 학습과 임계값 조정은 같은 문제에 대한 서로 다른 수단이고 함께 검토해야 한다.","bad":true},{"txt":"compute_sample_weight 는 테스트 세트에도 적용해야 하므로 누락이 결함이다.","bad":false},{"txt":"balanced 가중치는 항상 성능을 개선하므로 지표 선택과 무관하다.","bad":false},{"txt":"sample_weight 를 쓰면 모델이 데이터를 복제하므로 메모리가 두 배로 든다.","bad":false}],"ex":"결함 3가지: (1) 학습 목표와 평가 지표 불일치. (2) 목표 지표 미정의. (3) 임계값 미검토. 디스트랙터: 테스트 평가에 학습용 가중치를 적용하는 것은 오히려 왜곡이다. balanced 가 항상 좋지는 않다. 가중치는 손실 계산에만 쓰이고 데이터를 복제하지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"def train():\n    torch.manual_seed(42)\n    model = Net()\n    for epoch in range(100):\n        for xb, yb in loader:\n            loss = crit(model(xb), yb)\n            loss.backward()\n            opt.step()","items":[{"txt":"opt.zero_grad() 를 호출하지 않아 기울기가 배치마다 누적된다. 학습이 의도대로 진행되지 않는다.","bad":true},{"txt":"검증 루프가 없어 과적합 시점을 알 수 없다. 100 에포크를 무조건 돈다.","bad":true},{"txt":"시드만 고정하고 데이터로더 셔플·cudnn 결정성을 다루지 않아 재현이 완전하지 않다.","bad":true},{"txt":"loss.backward() 를 호출하면 기울기가 자동으로 초기화되므로 zero_grad 는 불필요하다.","bad":false},{"txt":"model.train() 을 호출하지 않으면 파라미터가 갱신되지 않는다.","bad":false},{"txt":"에포크 100 은 너무 적어 학습이 수렴하지 않는 것이 핵심 결함이다.","bad":false}],"ex":"결함 3가지: (1) zero_grad 누락 — PyTorch 학습 루프의 대표적 버그다. (2) 검증 루프 부재. (3) 불완전한 재현성. 디스트랙터: backward 는 기울기를 누적한다(초기화하지 않는다). model.train() 은 드롭아웃·배치정규화 모드를 바꿀 뿐 파라미터 갱신 자체는 opt.step 이 한다. 에포크 수는 데이터에 따라 다르다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"train_loader = DataLoader(ds, batch_size=64, shuffle=True)\nval_loader   = DataLoader(ds, batch_size=64, shuffle=False)","items":[{"txt":"학습과 검증이 같은 데이터셋을 가리킨다. 검증 성능이 학습 성능이 되어 과적합을 감지할 수 없다.","bad":true},{"txt":"분할하지 않은 채 두 로더를 만들었다. Subset 이나 random_split 으로 나눠야 한다.","bad":true},{"txt":"shuffle 값이 다르므로 두 로더는 서로 다른 데이터를 반환한다.","bad":false},{"txt":"batch_size 가 같으면 두 로더가 동일해지므로 크기를 달리해야 한다.","bad":false},{"txt":"DataLoader 는 같은 데이터셋을 공유하면 예외를 던지므로 실행되지 않는다.","bad":false},{"txt":"검증에는 shuffle=True 가 필요하므로 False 인 것이 결함이다.","bad":false}],"ex":"결함 2가지: 같은 데이터셋을 학습·검증에 함께 쓴 것이다. 눈에 잘 띄지 않는데 결과는 완전히 무의미해진다. 디스트랙터: 셔플 여부는 순서만 바꾸고 데이터 자체는 같다. 배치 크기는 무관하다. 데이터셋 공유는 허용된다. 검증에서는 셔플이 불필요하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"model.eval()\npreds = []\nfor xb, _ in loader:\n    preds.append(model(xb))\nloss = crit(torch.cat(preds), y)\nloss.backward()","items":[{"txt":"추론 구간을 torch.no_grad() 로 감싸지 않아 계산 그래프가 전부 메모리에 남는다. 큰 데이터에서 OOM 이 난다.","bad":true},{"txt":"eval 모드에서 backward 를 호출한다. 평가 코드에 기울기 계산이 섞여 있어 의도가 불명확하고 옵티마이저 상태를 오염시킬 수 있다.","bad":true},{"txt":"model.eval() 을 호출하면 기울기 계산이 자동으로 꺼지므로 no_grad 가 불필요하다.","bad":false},{"txt":"torch.cat 은 리스트를 받을 수 없으므로 stack 을 써야 한다.","bad":false},{"txt":"preds 를 CPU 로 옮기지 않으면 GPU 메모리가 부족해지는 것이 유일한 문제다.","bad":false},{"txt":"crit 을 배치 단위로 호출하지 않으면 손실 값이 항상 0 이 된다.","bad":false}],"ex":"결함 2가지: (1) no_grad 누락 — eval 모드는 기울기 계산을 끄지 않는다(가장 흔한 오해다). (2) 평가 코드의 backward. 디스트랙터: eval 은 드롭아웃·배치정규화 동작만 바꾼다. cat 은 텐서 리스트를 받는다. CPU 이동은 도움이 되지만 근본 원인은 그래프 보존이다. 전체 손실 계산은 정상적인 방식이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"best = None\nfor fold in folds:\n    m = train(fold.train)\n    if score(m, fold.val) &gt; best_score:\n        best, best_score = m, score(m, fold.val)\nfinal = best","items":[{"txt":"교차검증의 목적은 성능 추정인데 폴드 중 최고 모델을 골라 최종 모델로 삼았다. 그 점수는 낙관적이고 모델도 한 폴드에만 맞춰져 있다.","bad":true},{"txt":"교차검증 결과는 평균으로 성능을 추정하고, 최종 모델은 전체 학습 데이터로 다시 학습하는 것이 표준이다.","bad":true},{"txt":"폴드마다 점수를 두 번 계산해 낭비하고, 폴드별 점수를 기록하지 않아 분산을 알 수 없다.","bad":true},{"txt":"교차검증에서 최고 폴드를 고르면 앙상블 효과가 생겨 일반화 성능이 향상된다.","bad":false},{"txt":"폴드 수가 정해지지 않았으므로 코드가 실행되지 않는 것이 핵심 결함이다.","bad":false},{"txt":"전체 데이터로 재학습하면 검증 데이터가 학습에 들어가 누수가 되므로 해서는 안 된다.","bad":false}],"ex":"결함 3가지: (1) 교차검증의 목적 오해. (2) 최종 모델 학습 방식. (3) 분산 정보 미기록. 디스트랙터: 최고 폴드 선택은 앙상블이 아니라 체리피킹이다. folds 는 외부에서 주어진다. 최종 재학습은 표준 관행이며, 성능 추정은 이미 교차검증으로 끝났으므로 누수가 아니다."}],"th":{"sum":"ML 코드 리뷰는 대개 **누수(leakage) 사냥**이다: 학습이 알아서는 안 되는 정보를 어디서 얻었는가.","body":[{"h":"누수는 순서에서 온다","t":"스케일링·결측 대체·차원 축소·특성 선택·리샘플링·타깃 인코딩 — 이 중 하나라도 분할 전에 하면 테스트 정보가 학습에 흘러든다. 규칙은 하나다: fit 은 학습 폴드에서만, transform 은 양쪽에. Pipeline 으로 묶어 교차검증에 넣으면 구조적으로 막힌다. 조기 종료를 테스트 세트로 하는 것, 테스트로 하이퍼파라미터를 고르는 것도 같은 누수다."},{"h":"미래와 그룹","t":"예측 시점에 존재하지 않는 특성(다음 날 매출, 사후 집계)은 검증에서만 빛난다. 특성마다 '가용 시점' 을 확인한다. 같은 사용자·같은 세션의 행이 학습과 검증에 나뉘면 그것도 누수이므로 GroupKFold·TimeSeriesSplit 을 쓴다. 중복 행 역시 양쪽에 흩어질 수 있다."},{"h":"지표가 목표를 반영하는가","t":"불균형 데이터의 정확도는 아무것도 말해 주지 않는다. 클래스 가중치를 주면서 정확도로 평가하면 학습 목표와 평가가 어긋난다. 임계값 0.5 는 기본값일 뿐이고, 보정되지 않은 확률의 0.5 는 확률적 의미가 없다. 기준선과 비교하지 않은 수치는 좋은지 나쁜지 알 수 없다."},{"h":"학습-서빙 왜곡","t":"모델만 저장하고 전처리기를 빼면 서빙에서 다른 특성을 만든다. get_dummies 를 서빙에서 다시 호출하면 열 구성이 달라진다. 열 순서·미본 범주·라이브러리 버전은 모두 조용히 틀린 예측을 낸다. 저장 대상은 모델이 아니라 파이프라인 전체다."}],"code":{"c":"# 결함: 분할 전 스케일링 + 테스트로 튜닝 + 정확도만 봄\nXs = StandardScaler().fit_transform(X)          # 전체로 fit → 누수\nXtr, Xte, ytr, yte = train_test_split(Xs, y)\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    if m.score(Xte, yte) > best: best, bd = m.score(Xte, yte), d\nprint(best)                                      # 낙관적 수치\n\n# 고침: 파이프라인 + 검증/테스트 분리 + 지표 정의\nXtr, Xte, ytr, yte = train_test_split(X, y, stratify=y, random_state=42)\npipe = Pipeline([(\"sc\", StandardScaler()), (\"clf\", GradientBoostingClassifier())])\ngs = GridSearchCV(pipe, {\"clf__max_depth\":[3,5,7]},\n                  cv=StratifiedKFold(5, shuffle=True, random_state=42),\n                  scoring=\"average_precision\")   # 불균형이면 PR-AUC\ngs.fit(Xtr, ytr)                                 # 폴드 안에서만 fit → 누수 없음\nprint(gs.best_score_)                            # 튜닝 성능\nprint(average_precision_score(yte, gs.predict_proba(Xte)[:,1]))  # 테스트는 마지막 한 번","cap":"Pipeline + GridSearchCV 는 누수를 구조적으로 막는다"},"key":["fit 은 학습 폴드에서만. 스케일링·대체·PCA·특성선택·리샘플링 전부 해당","Pipeline 으로 묶어 교차검증에 넣으면 누수가 구조적으로 막힌다","테스트 세트로 튜닝·조기 종료를 하지 않는다. train/valid/test 세 갈래","특성마다 '예측 시점에 있는 값인가' 를 확인한다. 그룹·시간 구조면 전용 분할","불균형에 정확도 금지. 학습 목표와 평가 지표를 일치시키고 기준선과 비교한다","저장하는 것은 모델이 아니라 파이프라인 전체 + 버전 + 데이터 버전"]}}]},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"학습 시뮬레이션","lv":3,"q":"<b>경사 하강법</b>으로 f(x)=(x-3)² 의 최솟값을 찾으세요. 학습률 0.1 로 20번 갱신하며 <code>snap(\"step \"+i, [x], {loss})</code> 로 기록하세요.","src":"function gd() {\n  let x = 10;\n  const lr = 0.1;\n  // 여기에 구현하세요 — 기울기는 2*(x-3) 입니다\n  return Math.round(x * 100) / 100;\n}\n\nRESULT = gd();","tests":[{"d":"최솟값 3에 가까워진다","js":"Math.abs(RESULT-3)<0.2"},{"d":"20번 갱신한다","js":"FRAMES.length===20"},{"d":"손실이 매 단계 줄어든다","js":"FRAMES.every((f,i)=>i===0||f.opt.loss<=FRAMES[i-1].opt.loss)"},{"d":"x 가 최솟값을 지나치지 않는다","js":"FRAMES.every(f=>f.value[0]>=3)"},{"d":"초기값보다 손실이 크게 줄었다","js":"FRAMES[FRAMES.length-1].opt.loss<1"}],"ex":"학습률이 결과를 좌우합니다. 0.1 처럼 적당하면 최솟값에 <b>단조롭게</b> 다가가고(검사가 그것을 확인합니다), 너무 크면(예: 1.1) 최솟값을 지나쳐 <b>진동하며 발산</b>하고, 너무 작으면 수렴이 하염없이 느려집니다. 여기서는 볼록 함수라 <b>지역 최솟값이 곧 전역 최솟값</b>이지만, 신경망의 손실면은 그렇지 않아서 초기값·모멘텀·스케줄이 함께 필요합니다."},{"t":"sim","k":"학습 시뮬레이션","lv":3,"q":"<b>과적합</b>을 모델링하세요. 학습 손실은 계속 줄지만 검증 손실은 어느 시점부터 오릅니다. 매 에폭을 <code>snap</code> 으로 기록하고 <b>검증 손실이 최소인 에폭</b>을 돌려주세요.","src":"const TRAIN = [0.9,0.7,0.5,0.35,0.25,0.18,0.12,0.08,0.05,0.03];\nconst VALID = [0.95,0.75,0.55,0.42,0.38,0.40,0.45,0.52,0.60,0.71];\n\nfunction earlyStop() {\n  let best = 0;\n  // 여기에 구현하세요\n  return best;\n}\n\nRESULT = earlyStop();","tests":[{"d":"검증 손실이 최소인 에폭은 4다","js":"RESULT===4"},{"d":"에폭마다 장면이 기록된다","js":"FRAMES.length===10"},{"d":"학습 손실은 계속 줄어든다","js":"FRAMES.every((f,i)=>i===0||f.value[0]<FRAMES[i-1].value[0])"},{"d":"어느 시점부터 검증 손실이 오른다","js":"FRAMES.some((f,i)=>i>0&&f.value[1]>FRAMES[i-1].value[1])"},{"d":"학습·검증 격차가 벌어진다","js":"FRAMES[9].opt.gap>FRAMES[0].opt.gap"}],"ex":"학습 손실만 보면 모델이 계속 좋아지는 것처럼 보입니다 — 실제로는 <b>학습 데이터를 외우기 시작한</b> 것입니다. 검증 손실이 오르기 시작하는 지점이 <b>일반화 성능의 정점</b>이고, 조기 종료(early stopping)는 그 지점의 가중치를 남깁니다. 검사가 확인하는 <b>격차 확대</b>가 과적합의 정의 그 자체입니다. 대응은 조기 종료 외에 정규화·드롭아웃·데이터 증강·모델 축소가 있습니다."},{"t":"sim","k":"평가 시뮬레이션","lv":3,"q":"<b>불균형 데이터에서 정확도의 함정</b>을 보이세요. 양성이 1% 인 데이터에서 '전부 음성' 이라고 답하는 모델의 정확도·정밀도·재현율을 계산해 <code>[정확도, 정밀도, 재현율]</code> 로 돌려주세요(소수 둘째 자리 반올림, 정의 불가는 0).","src":"const N = 1000, POS = 10;\n\nfunction naive() {\n  // 모델은 모두 음성(0)으로 예측합니다\n  return [0, 0, 0];\n}\n\nRESULT = naive();","tests":[{"d":"정확도가 0.99 로 매우 높다","js":"RESULT[0]===0.99"},{"d":"정밀도가 0이다","js":"RESULT[1]===0"},{"d":"재현율이 0이다","js":"RESULT[2]===0"},{"d":"혼동행렬과 지표가 기록된다","js":"FRAMES.length===2"},{"d":"참양성이 하나도 없다","js":"FRAMES[0].value[0]===0"}],"ex":"<b>정확도 99%</b> 인데 양성을 하나도 못 맞히는 모델입니다. 사기 탐지·질병 진단처럼 <b>양성이 희귀한</b> 문제에서 정확도는 아무 의미가 없습니다. 봐야 할 것은 <b>정밀도(맞다고 한 것 중 진짜)</b>와 <b>재현율(진짜 중 찾아낸 것)</b>이고, 둘은 대개 상충합니다 — 임계값을 낮추면 재현율이 오르고 정밀도가 떨어집니다. 어느 쪽이 중요한지는 <b>틀렸을 때의 비용</b>이 정합니다: 암 검진은 재현율, 스팸 차단은 정밀도."},{"t":"sim","k":"평가 시뮬레이션","lv":4,"q":"<b>데이터 누수</b>를 모델링하세요. 정규화를 전체 데이터로 먼저 한 경우와 학습 데이터로만 한 경우, 검증 세트의 평균이 각각 얼마인지 <code>[누수, 정상]</code> 으로 돌려주세요(소수 둘째 자리).","src":"const TRAIN = [1, 2, 3, 4], VALID = [10, 12];\nfunction mean(a){ return a.reduce((x,y)=>x+y,0)/a.length; }\n\nfunction leak() {\n  // 누수: 전체(TRAIN+VALID)의 평균으로 중심화\n  // 정상: TRAIN 의 평균으로 중심화\n  return [0, 0];\n}\n\nRESULT = leak();","tests":[{"d":"누수 방식의 검증 평균이 더 0에 가깝다","js":"Math.abs(RESULT[0])<Math.abs(RESULT[1])"},{"d":"정상 방식에서는 검증 평균이 크게 남는다","js":"RESULT[1]>5"},{"d":"두 방식의 장면이 기록된다","js":"FRAMES.length===2"},{"d":"전체 평균이 학습 평균보다 크다","js":"FRAMES[0].opt.m>FRAMES[1].opt.m"},{"d":"두 결과가 다르다","js":"RESULT[0]!==RESULT[1]"}],"ex":"전체 데이터로 정규화하면 <b>검증 세트의 정보가 전처리에 스며듭니다</b> — 검증 평균이 0에 가까워져 성능이 실제보다 좋아 보입니다. 운영에서는 미래 데이터의 통계를 알 수 없으므로 이 이점이 사라지고, <b>배포 후 성능이 뚝 떨어집니다.</b> 규칙은 하나입니다: <b>모든 전처리 통계는 학습 데이터에서만</b> 계산하고 검증·테스트에는 그대로 적용합니다. 파이프라인 객체로 묶어 두면 실수를 구조적으로 막을 수 있습니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"학습 시뮬레이션","lv":2,"q":"<b>미니배치 학습</b>을 모델링하세요. 데이터 10개를 배치 크기 3으로 나눠 2에폭 돌립니다. 배치마다 <code>snap</code> 으로 기록하고 <b>총 갱신 횟수</b>를 돌려주세요.","src":"const N = 10, BATCH = 3, EPOCHS = 2;\n\nfunction train() {\n  let steps = 0;\n  // 여기에 구현하세요 — 마지막 배치는 크기가 작을 수 있습니다\n  return steps;\n}\n\nRESULT = train();","tests":[{"d":"총 갱신은 8번이다","js":"RESULT===8"},{"d":"배치마다 장면이 기록된다","js":"FRAMES.length===8"},{"d":"마지막 배치의 크기가 1이다","js":"FRAMES[3].value[0]===1"},{"d":"에폭이 두 번 돈다","js":"new Set(FRAMES.map(f=>f.opt.epoch)).size===2"},{"d":"갱신 횟수가 1씩 증가한다","js":"FRAMES.every((f,i)=>f.opt.steps===i+1)"}],"ex":"배치 크기는 <b>속도·메모리·일반화</b>의 절충입니다. 크면 GPU 를 효율적으로 쓰고 기울기가 안정적이지만 메모리를 많이 먹고, 작으면 갱신이 잦아 <b>노이즈가 정규화처럼</b> 작동하기도 합니다. 그리고 <b>나누어떨어지지 않는 마지막 배치</b>가 자주 버그를 만듭니다 — 크기를 상수로 가정한 코드가 여기서 깨집니다. 배치 정규화를 쓰면 배치가 1인 경우 통계가 불안정해지는 문제도 함께 옵니다."},{"t":"sim","k":"평가 시뮬레이션","lv":3,"q":"<b>K-겹 교차 검증</b>을 모델링하세요. 데이터 10개를 5겹으로 나누고, 각 겹이 한 번씩 검증이 되게 하세요. 겹마다 <code>snap</code> 으로 학습·검증 크기를 기록하고 <b>전체 검증에 쓰인 인덱스 수</b>를 돌려주세요.","src":"const N = 10, K = 5;\n\nfunction kfold() {\n  const used = new Set();\n  // 여기에 구현하세요\n  return used.size;\n}\n\nRESULT = kfold();","tests":[{"d":"모든 데이터가 정확히 한 번씩 검증에 쓰인다","js":"RESULT===10"},{"d":"겹이 5개다","js":"FRAMES.length===5"},{"d":"매 겹의 학습·검증 크기가 8과 2다","js":"FRAMES.every(f=>f.value[0]===8&&f.value[1]===2)"},{"d":"검증 인덱스가 겹치지 않는다","js":"(function(){const all=FRAMES.flatMap(f=>f.opt.valid);return new Set(all).size===all.length;})()"},{"d":"검증 인덱스가 순서대로 나뉜다","js":"FRAMES.every((f,i)=>f.opt.valid[0]===i*2)"}],"ex":"단일 분할은 <b>운에 좌우</b>됩니다 — 우연히 쉬운 검증 세트가 걸리면 성능이 과대평가됩니다. K-겹은 모든 데이터가 한 번씩 검증에 쓰이게 해 추정의 <b>분산을 줄입니다</b>(대신 K배 학습). 주의할 것 두 가지: 시계열 데이터는 <b>미래로 학습해 과거를 검증</b>하면 안 되므로 시간 순 분할을 쓰고, 같은 사용자의 데이터가 학습과 검증에 나뉘어 들어가면 <b>그룹 누수</b>가 됩니다."},{"t":"sim","k":"학습 시뮬레이션","lv":3,"q":"<b>학습률이 너무 클 때의 발산</b>을 보이세요. 같은 함수 f(x)=(x-3)² 에서 학습률 0.1 과 1.1 로 각각 10번 갱신하고, 최종 손실을 <code>[안정, 발산]</code> 으로 돌려주세요.","src":"function compare() {\n  // 여기에 구현하세요 — 두 학습률로 각각 돌리고 snap 으로 기록하세요\n  return [0, 0];\n}\n\nRESULT = compare();","tests":[{"d":"안정적인 학습률은 손실을 크게 줄인다 (49 → 0.56)","js":"RESULT[0]<1"},{"d":"큰 학습률은 손실이 폭발한다","js":"RESULT[1]>1000"},{"d":"두 실행이 각각 10단계씩 기록된다","js":"FRAMES.filter(f=>f.opt.lr===0.1).length===10 && FRAMES.filter(f=>f.opt.lr===1.1).length===10"},{"d":"안정 실행의 손실은 단조 감소한다","js":"(function(){const f=FRAMES.filter(x=>x.opt.lr===0.1);return f.every((x,i)=>i===0||x.opt.loss<=f[i-1].opt.loss);})()"},{"d":"발산 실행의 손실은 커진다","js":"(function(){const f=FRAMES.filter(x=>x.opt.lr===1.1);return f[f.length-1].opt.loss>f[0].opt.loss;})()"}],"ex":"기울기의 <b>반대 방향</b>으로 가는 것은 맞지만, <b>얼마나 갈지</b>가 학습률입니다. 너무 크면 최솟값을 지나쳐 반대편 더 높은 곳에 착지하고, 그 지점의 기울기는 더 크므로 다음 걸음은 더 멀리 갑니다 — 이 되먹임이 <b>발산</b>입니다. 실무에서 손실이 NaN 이 되는 사고의 가장 흔한 원인이 과도한 학습률이고, 대응은 학습률 낮추기·워밍업·기울기 클리핑입니다."},{"t":"sim","k":"평가 시뮬레이션","lv":4,"q":"<b>임계값과 정밀도-재현율 상충</b>을 보이세요. 점수와 실제 라벨이 주어집니다. 임계값 0.3·0.5·0.7 에서 정밀도와 재현율을 계산해 <code>snap</code> 으로 기록하고, <b>재현율이 1.0 인 가장 높은 임계값</b>을 돌려주세요.","src":"const DATA = [\n  {s:0.9, y:1}, {s:0.75, y:1}, {s:0.6, y:0}, {s:0.55, y:1},\n  {s:0.4, y:0}, {s:0.35, y:1}, {s:0.2, y:0}, {s:0.1, y:0}\n];\n\nfunction sweep() {\n  let ans = 0;\n  // 여기에 구현하세요 — 임계값 이상이면 양성으로 예측합니다\n  return ans;\n}\n\nRESULT = sweep();","tests":[{"d":"재현율 1.0 을 유지하는 가장 높은 임계값은 0.3 이다","js":"RESULT===0.3"},{"d":"세 임계값의 장면이 기록된다","js":"FRAMES.length===3"},{"d":"임계값이 오르면 재현율이 떨어진다","js":"(function(){const r=FRAMES.map(f=>f.value[1]);return r.every((x,i)=>i===0||x<=r[i-1]);})()"},{"d":"임계값이 오르면 정밀도가 오른다","js":"(function(){const p=FRAMES.map(f=>f.value[0]);return p.every((x,i)=>i===0||x>=p[i-1]);})()"},{"d":"가장 높은 임계값에서 정밀도가 1.0 이다","js":"FRAMES[2].value[0]===1"}],"ex":"검사 두 개가 <b>상충 관계</b>를 그대로 보여 줍니다 — 임계값을 올리면 정밀도가 오르고 재현율이 떨어집니다. 그래서 '모델 성능' 은 하나의 숫자가 아니라 <b>곡선</b>이고, 운영에서 고르는 것은 모델뿐 아니라 <b>임계값</b>입니다. 임계값은 기술이 아니라 <b>비용으로</b> 정합니다: 놓친 사기 1건의 손실과 정상 거래를 막았을 때의 불만을 견줍니다. 불균형 데이터에서는 ROC 보다 <b>PR 곡선</b>이 상황을 더 정직하게 보여 줍니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}]},{"t":"실행형 실전 — 학습 과정을 직접 짠다","l":[{"t":"경사·전처리·분할·조기종료","xp":80,"th":{"sum":"학습이 안 되는 원인은 대개 **모델이 아니라 절차**다. 학습률·전처리 순서·분할 방식이 성능을 먼저 결정한다.","body":[{"h":"방향과 크기","t":"경사하강은 기울기의 **반대 방향**으로 이동한다 — 부호를 잘못 쓰면 발산한다. 이미 최적인 지점에서는 기울기가 0이라 제자리에 머물러야 하고, 그렇지 않다면 구현이 틀린 것이다. 손실이 줄지 않고 튄다면 가장 먼저 학습률을 낮춰 본다."},{"h":"누수는 조용히 성능을 부풀린다","t":"전처리 파라미터는 **학습 데이터에서만** 구해야 한다. 전체로 평균을 내면 테스트 정보가 학습에 새어 들어가 검증 점수가 좋아 보이고, 서비스에 올린 뒤에야 무너진다. 시계열에 무작위 분할을 쓰는 것도 같은 종류의 누수다. 과적합은 **검증 손실이 오르기 시작하는** 지점에서 드러나므로 조기 종료로 끊는다."}],"code":{"c":"# 누수\nscaler.fit(전체);  train, test = split(전체)\n# 올바름\ntrain, test = split(전체);  scaler.fit(train)","cap":"전처리는 분할 뒤에"},"key":["기울기의 반대 방향으로 이동한다 — 최적점에서는 멈춘다","전처리 파라미터는 학습 데이터에서만 구한다","시계열에 무작위 분할은 누수다","같은 사용자의 행이 학습·테스트에 나뉘면 안 된다","조기 종료 시점을 테스트 세트로 고르면 그것도 누수다"]},"q":[{"t":"code","run":"js","k":"경사하강 한 걸음","cat":"internals","q":"단순 선형회귀 <code>y = w·x + b</code> 의 <b>MSE 손실</b>에 대해 경사하강 한 스텝을 구현하세요. <code>step(w, b, xs, ys, lr)</code> 는 갱신된 <code>[w, b]</code> 를 돌려줍니다. 손실은 <code>mean((wx+b−y)²)</code> 입니다.","src":"function step(w, b, xs, ys, lr) {\n  // TODO: 기울기를 구해 w, b 를 갱신\n  return [w, b];\n}","sol":"function step(w, b, xs, ys, lr) {\n  const n = xs.length;\n  let gw = 0;\n  let gb = 0;\n  xs.forEach((x, i) => {\n    const err = w * x + b - ys[i];\n    gw += 2 * err * x;\n    gb += 2 * err;\n  });\n  return [w - (lr * gw) / n, b - (lr * gb) / n];\n}","tests":[{"in":"step(0,0,[1,2],[2,4],0.1)","out":"[1,0.6000000000000001]"},{"in":"step(2,0,[1,2],[2,4],0.1)","out":"[2,0]"},{"in":"step(0,0,[1],[1],0.5)","out":"[1,1]"},{"in":"step(1,0,[0],[0],0.1)","out":"[1,0]"}],"edge":[{"in":"step(0,0,[1,2],[2,4],0)","out":"[0,0]"},{"in":"(() => { const L=(w,b)=>[1,2].reduce((s,x,i)=>s+Math.pow(w*x+b-[2,4][i],2),0)/2; const [w,b]=step(0,0,[1,2],[2,4],0.1); return L(w,b) < L(0,0); })()","out":"true"}],"ex":"🎯 경사하강은 '<b>손실이 줄어드는 방향으로 조금 이동</b>' 을 반복합니다. 기울기는 손실이 <b>커지는</b> 방향이므로 빼야 합니다 — 부호를 잘못 쓰면 손실이 발산합니다.\n💡 이미 정답인 지점(<code>w=2, b=0</code>)에서는 오차가 0이라 기울기도 0이고 <b>제자리에 머뭅니다</b>. 테스트 2가 그것을 확인합니다 — 수렴한 뒤에도 움직인다면 구현이 틀린 것입니다.\n⚠️ <code>2/n</code> 계수를 빼먹어도 방향은 같아서 <b>학습은 됩니다</b>. 다만 실효 학습률이 달라지므로 논문의 하이퍼파라미터를 그대로 썼을 때 결과가 재현되지 않습니다.\n🔧 학습률이 너무 크면 골짜기를 건너뛰며 발산하고, 너무 작으면 영원히 안 끝납니다. 손실이 <b>줄지 않고 튄다면</b> 가장 먼저 학습률을 낮춰 보세요."},{"t":"code","run":"js","k":"표준화와 데이터 누수","cat":"internals","q":"학습 데이터로 <b>평균·표준편차를 구해</b> 학습·테스트를 모두 변환하세요. <code>fit(train)</code> 은 <code>{mean, std}</code> 를, <code>apply(xs, p)</code> 는 변환된 배열을 돌려줍니다. <b>테스트 데이터로 다시 fit 하면 안 됩니다</b>.","src":"function fit(train) {\n  // TODO: 평균·표준편차\n  return { mean: 0, std: 1 };\n}\n\nfunction apply(xs, p) {\n  // TODO: (x - mean) / std\n  return xs.slice();\n}","sol":"function fit(train) {\n  const n = train.length;\n  const mean = train.reduce((a, b) => a + b, 0) / n;\n  const v = train.reduce((a, b) => a + (b - mean) * (b - mean), 0) / n;\n  const std = Math.sqrt(v);\n  return { mean, std: std === 0 ? 1 : std };\n}\n\nfunction apply(xs, p) {\n  return xs.map((x) => (x - p.mean) / p.std);\n}","tests":[{"in":"fit([1,2,3]).mean","out":"2"},{"in":"apply([1,2,3], fit([1,2,3]))[1]","out":"0"},{"in":"(() => { const p=fit([1,2,3]); return apply([4], p)[0] > apply([3], p)[0]; })()","out":"true"},{"in":"fit([5,5,5]).std","out":"1"}],"edge":[{"in":"apply([], fit([1,2,3]))","out":"[]"},{"in":"(() => { const p=fit([0,10]); return apply([5], p)[0]; })()","out":"0"}],"ex":"🎯 전처리 파라미터는 <b>학습 데이터에서만</b> 구해야 합니다. 전체 데이터로 평균을 내면 테스트 정보가 학습에 새어 들어가(<b>데이터 누수</b>) 성능이 실제보다 좋게 나옵니다.\n⚠️ 이 누수는 <b>발견하기 어렵습니다</b> — 오류가 나지 않고 검증 점수도 좋아 보이며, 실제 서비스에 올린 뒤에야 성능이 무너집니다.\n💡 테스트 3이 중요한 성질을 확인합니다. 학습 때 못 본 값(4)도 <b>같은 파라미터로</b> 변환되어야 순서가 보존됩니다. 테스트마다 다시 fit 하면 같은 값이 상황에 따라 다르게 변환됩니다.\n🔧 표준편차가 0인 상수 특성은 <b>0으로 나눔</b>이 됩니다. 1로 대체하거나 그 특성을 아예 버려야 하고, 상수 특성은 예측에 기여하지 않으므로 버리는 편이 낫습니다."},{"t":"code","run":"js","k":"학습·검증 분할과 시계열","cat":"internals","q":"데이터를 학습·테스트로 나누세요. <code>splitRandom(n, ratio)</code> 는 앞 <code>ratio</code> 만큼을 학습으로(결정적), <code>splitTime(times, cut)</code> 는 <b>cut 이전을 학습, 이후를 테스트</b>로 나눕니다. 각각 <code>{train, test}</code> 인덱스 배열입니다.","src":"function splitRandom(n, ratio) {\n  // TODO: 앞 ratio 를 학습\n  return { train: [], test: [] };\n}\n\nfunction splitTime(times, cut) {\n  // TODO: 시각 기준 분할\n  return { train: [], test: [] };\n}","sol":"function splitRandom(n, ratio) {\n  const k = Math.floor(n * ratio);\n  const all = Array.from({ length: n }, (_, i) => i);\n  return { train: all.slice(0, k), test: all.slice(k) };\n}\n\nfunction splitTime(times, cut) {\n  const train = [];\n  const test = [];\n  times.forEach((t, i) => (t < cut ? train : test).push(i));\n  return { train, test };\n}","tests":[{"in":"splitRandom(10,0.8).train.length","out":"8"},{"in":"splitRandom(10,0.8).test","out":"[8,9]"},{"in":"splitTime([1,2,3,4],3)","out":"{train:[0,1],test:[2,3]}"},{"in":"splitTime([5,1,3],3).train","out":"[1]"}],"edge":[{"in":"splitRandom(0,0.8)","out":"{train:[],test:[]}"},{"in":"splitTime([1,2],10)","out":"{train:[0,1],test:[]}"}],"ex":"🎯 시계열에서 <b>무작위 분할은 곧 누수</b>입니다. 미래 데이터로 학습해 과거를 예측하게 되므로 검증 점수가 비현실적으로 좋아지고, 실제 서비스에서는 그 성능이 안 나옵니다.\n💡 시각 기준 분할은 <b>실제 사용 조건</b>을 흉내 냅니다 — 우리는 항상 '지금까지의 데이터로 앞을 예측' 하기 때문입니다.\n⚠️ 시계열이 아니어도 무작위 분할이 위험할 때가 있습니다. 같은 사용자의 여러 행이 학습과 테스트에 <b>나뉘어 들어가면</b> 모델이 그 사용자를 외워 버립니다 — 그룹 단위로 나눠야 합니다.\n🔧 이 문항의 <code>splitRandom</code> 은 채점을 위해 결정적으로 만들었습니다. 실제로는 섞되 <b>시드를 고정</b>해야 실험이 재현됩니다."},{"t":"code","run":"js","k":"과적합의 신호","cat":"internals","q":"에포크별 학습·검증 손실이 주어집니다. <b>검증 손실이 최소가 된 뒤 patience 번 연속 나아지지 않으면</b> 멈추는 조기 종료를 구현하세요. <code>earlyStop(valLoss, patience)</code> 는 <b>멈추는 에포크 인덱스</b>를(안 멈추면 -1) 돌려줍니다.","src":"function earlyStop(valLoss, patience) {\n  // TODO: 최고 기록 뒤 patience 번 개선 없으면 중단\n  return -1;\n}","sol":"function earlyStop(valLoss, patience) {\n  let best = Infinity;\n  let wait = 0;\n  for (let i = 0; i < valLoss.length; i++) {\n    if (valLoss[i] < best) { best = valLoss[i]; wait = 0; continue; }\n    wait += 1;\n    if (wait >= patience) return i;\n  }\n  return -1;\n}","tests":[{"in":"earlyStop([1.0,0.8,0.6,0.7,0.75],2)","out":"4"},{"in":"earlyStop([1.0,0.8,0.6,0.5,0.4],2)","out":"-1"},{"in":"earlyStop([1.0,1.1,1.2],2)","out":"2"},{"in":"earlyStop([1.0,0.9,1.0,0.8,0.9,1.0],2)","out":"5"}],"edge":[{"in":"earlyStop([],2)","out":"-1"},{"in":"earlyStop([1.0,1.1],1)","out":"1"}],"ex":"🎯 과적합은 <b>학습 손실은 계속 줄어드는데 검증 손실이 올라가기 시작하는</b> 지점에서 드러납니다. 모델이 일반적인 규칙 대신 학습 데이터의 잡음을 외우기 시작한 것입니다.\n🔧 조기 종료는 가장 값싼 정규화입니다 — 하이퍼파라미터 하나(patience)만 정하면 되고, 학습 시간까지 줄여 줍니다.\n💡 <b>patience 가 필요한 이유</b>는 검증 손실이 매끄럽게 움직이지 않기 때문입니다. 한 번 올랐다고 멈추면 잡음에 속아 너무 일찍 끝냅니다 — 테스트 4가 오르내리는 경우를 검사합니다.\n⚠️ 조기 종료 시점을 <b>테스트 세트로 고르면</b> 그 자체가 누수입니다. 검증 세트로 멈추고, 최종 성능은 건드리지 않은 테스트 세트로 한 번만 재야 합니다."}]}]}]);
